    // ==================== واجهة نتائج - Glassmorphism داكن (v10.0) ====================
    function ensurePanelStyles() {
        ensurePopupSystem(); // (v29.32.0) tokens + طبقة الـpopup الموحّدة + تحويل الإيموجي لأيقونات
        if (document.getElementById('tx-panel-style')) return;
        const style = document.createElement('style');
        style.id = 'tx-panel-style';
        style.textContent = `

            /* ===== (v29.32.0) نظام الـPopup الموحّد - كله على tokens نظام التصميم (--tx-*) ===== */
            .tx-panel-overlay {
                position: fixed; inset: 0; background: rgba(4,6,10,0.55);
                backdrop-filter: blur(5px); -webkit-backdrop-filter: blur(5px); z-index: 200000;
                display: flex; align-items: center; justify-content: center;
                animation: tx-fade-in 0.16s var(--tx-ease);
            }
            @keyframes tx-fade-in { from { opacity: 0; } to { opacity: 1; } }
            @keyframes tx-pop-in { from { transform: scale(0.97) translateY(8px); opacity: 0; } to { transform: scale(1) translateY(0); opacity: 1; } }
            .tx-panel-box {
                width: 640px; max-width: 92vw; max-height: 82vh;
                background: var(--tx-surface-0);
                backdrop-filter: blur(16px) saturate(160%);
                -webkit-backdrop-filter: blur(16px) saturate(160%);
                border: 1px solid rgba(var(--tx-accent), 0.3);
                border-radius: var(--tx-radius-lg);
                box-shadow: var(--tx-shadow-pop);
                display: flex; flex-direction: column;
                overflow: hidden;
                font-family: var(--tx-font); color: var(--tx-text);
                direction: rtl;
                animation: tx-pop-in 0.18s var(--tx-ease);
                position: relative;
            }
            .tx-panel-header {
                display: flex; align-items: center; justify-content: space-between; gap: 10px;
                padding: 12px 14px; border-bottom: 1px solid var(--tx-border);
            }
            .tx-panel-title { color: var(--tx-text); font: 800 14px var(--tx-font); display: flex; align-items: center; gap: 8px; }
            .tx-panel-title > .tx-emo:first-child:not(.is-ok):not(.is-warn):not(.is-danger):not(.is-info) { color: rgb(var(--tx-accent)); }
            .tx-panel-badge {
                background: var(--tx-surface-2); color: var(--tx-text-dim); font: 800 10.5px/16px var(--tx-font);
                padding: 1px 9px; border-radius: 999px; font-variant-numeric: tabular-nums;
            }
            .tx-panel-badge.pulse { background: rgba(var(--tx-danger), 0.18); color: #fecaca; animation: tx-badge-pulse 1.8s infinite; }
            @keyframes tx-badge-pulse {
                0% { box-shadow: 0 0 0 0 rgba(var(--tx-danger), 0.45); }
                70% { box-shadow: 0 0 0 7px rgba(var(--tx-danger), 0); }
                100% { box-shadow: 0 0 0 0 rgba(var(--tx-danger), 0); }
            }
            .tx-panel-actions { display: flex; align-items: center; gap: 8px; }
            .tx-panel-btn {
                display: inline-flex; align-items: center; justify-content: center; gap: 6px;
                padding: 6px 12px; border-radius: var(--tx-radius-md); cursor: pointer; white-space: nowrap;
                background: var(--tx-surface-1); border: 1px solid var(--tx-border); color: var(--tx-text);
                font: 700 11.5px var(--tx-font);
                transition: background 0.15s var(--tx-ease), border-color 0.15s var(--tx-ease), box-shadow 0.15s var(--tx-ease), transform 0.15s var(--tx-ease);
            }
            .tx-panel-btn:hover { background: var(--tx-surface-2); border-color: rgba(var(--tx-accent), 0.65); }
            .tx-panel-btn:focus-visible { outline: 2px solid rgba(var(--tx-accent), 0.85); outline-offset: 1px; }
            .tx-panel-btn.copy   { background: rgba(var(--tx-accent), 0.14); border-color: rgba(var(--tx-accent), 0.5); color: #ccfbf1; }
            .tx-panel-btn.fix    { background: rgba(var(--tx-ok), 0.13);     border-color: rgba(var(--tx-ok), 0.5);     color: #bbf7d0; }
            .tx-panel-btn.warn   { background: rgba(var(--tx-warn), 0.14);   border-color: rgba(var(--tx-warn), 0.55);   color: #fde68a; }
            .tx-panel-btn.danger { background: rgba(var(--tx-danger), 0.14); border-color: rgba(var(--tx-danger), 0.55); color: #fecaca; }
            .tx-panel-btn.info   { background: rgba(var(--tx-info), 0.13);   border-color: rgba(var(--tx-info), 0.5);   color: #bfdbfe; }
            .tx-panel-btn.review { background: rgba(var(--tx-review), 0.14); border-color: rgba(var(--tx-review), 0.5); color: #ddd6fe; }
            .tx-panel-btn.copy:hover   { background: rgba(var(--tx-accent), 0.24); box-shadow: 0 0 10px rgba(var(--tx-accent), 0.35); }
            .tx-panel-btn.fix:hover    { background: rgba(var(--tx-ok), 0.24);     border-color: rgba(var(--tx-ok), 0.85);     box-shadow: 0 0 10px rgba(var(--tx-ok), 0.35); }
            .tx-panel-btn.warn:hover   { background: rgba(var(--tx-warn), 0.24);   border-color: rgba(var(--tx-warn), 0.85);   box-shadow: 0 0 10px rgba(var(--tx-warn), 0.35); }
            .tx-panel-btn.danger:hover { background: rgba(var(--tx-danger), 0.24); border-color: rgba(var(--tx-danger), 0.85); box-shadow: 0 0 10px rgba(var(--tx-danger), 0.35); }
            .tx-panel-btn.info:hover   { background: rgba(var(--tx-info), 0.24);   border-color: rgba(var(--tx-info), 0.85);   box-shadow: 0 0 10px rgba(var(--tx-info), 0.35); }
            .tx-panel-btn.review:hover { background: rgba(var(--tx-review), 0.24); border-color: rgba(var(--tx-review), 0.85); box-shadow: 0 0 10px rgba(var(--tx-review), 0.35); }
            .tx-panel-btn:disabled { opacity: 0.5; cursor: not-allowed; box-shadow: none !important; }
            .tx-panel-btn.close-icon {
                width: 28px; height: 28px; padding: 0; border-radius: 50%;
                background: var(--tx-surface-1); color: var(--tx-text-dim); border: 1px solid var(--tx-border);
            }
            .tx-panel-btn.close-icon:hover { background: rgba(var(--tx-danger), 0.18); color: #fecaca; border-color: rgba(var(--tx-danger), 0.5); box-shadow: none; }
            .tx-panel-footer {
                display: flex; justify-content: flex-end; align-items: center; gap: 10px;
                padding: 12px 14px; border-top: 1px solid var(--tx-border);
            }
            .tx-panel-body { padding: 12px 14px 14px; overflow-y: auto; flex: 1; scrollbar-width: thin; scrollbar-color: rgba(148,163,184,0.35) transparent; }
            .tx-panel-body:focus, .tx-panel-body:focus-visible { outline: none !important; box-shadow: none !important; }
            .tx-panel-empty {
                color: #bbf7d0; font-size: 13px; text-align: center; padding: 28px 18px; font-weight: 700;
                background: rgba(var(--tx-ok), 0.08); border: 1px solid rgba(var(--tx-ok), 0.25); border-radius: var(--tx-radius-lg);
            }
            .tx-panel-heading {
                color: #99f6e4; font: 800 12.5px var(--tx-font); margin: 14px 0 8px;
                display: flex; align-items: center; gap: 6px;
            }
            .tx-panel-heading:first-child { margin-top: 0; }
            .tx-panel-item {
                display: flex; align-items: center; justify-content: space-between; gap: 8px;
                background: var(--tx-surface-1);
                border-right: 3px solid rgba(148,163,184,0.4);
                border-radius: var(--tx-radius-md); padding: 8px 10px; margin-bottom: 6px;
                color: var(--tx-text); font-size: 12.5px; line-height: 1.6;
                transition: background 0.15s var(--tx-ease), border-color 0.15s var(--tx-ease), box-shadow 0.15s var(--tx-ease);
            }
            .tx-panel-item.warn { border-right-color: rgb(var(--tx-danger)); background: rgba(var(--tx-danger), 0.07); }
            .tx-panel-item.info { border-right-color: rgb(var(--tx-info));   background: rgba(var(--tx-info), 0.07); }
            .tx-panel-item.ok   { border-right-color: rgb(var(--tx-ok));     background: rgba(var(--tx-ok), 0.07); }
            .tx-panel-item:hover { background: var(--tx-surface-2); }
            .tx-panel-item.jumpable { cursor: pointer; }
            .tx-panel-item.jumpable:hover { border-right-color: rgb(var(--tx-accent)); box-shadow: inset 0 0 0 1px rgba(var(--tx-accent), 0.35); }
            .tx-panel-item-text { flex: 1; }
            .tx-item-copy {
                display: inline-flex; align-items: center; gap: 4px;
                opacity: 0; flex-shrink: 0; background: var(--tx-surface-2); border: 1px solid var(--tx-border-strong);
                border-radius: var(--tx-radius-sm); color: var(--tx-text); font: 700 10.5px var(--tx-font); padding: 3px 8px; cursor: pointer;
                transition: opacity 0.15s var(--tx-ease), background 0.15s var(--tx-ease), border-color 0.15s var(--tx-ease);
            }
            .tx-panel-item:hover .tx-item-copy { opacity: 1; }
            .tx-item-copy:hover { background: rgba(var(--tx-accent), 0.24); border-color: rgba(var(--tx-accent), 0.65); }
            .tx-panel-num {
                display: inline-block; background: var(--tx-surface-2); color: #fff;
                padding: 1px 7px; border-radius: 6px; font-weight: 800; font-size: 11.5px; font-variant-numeric: tabular-nums;
            }
            .tx-panel-body::-webkit-scrollbar { width: 6px; }
            .tx-panel-body::-webkit-scrollbar-track { background: transparent; }
            .tx-panel-body::-webkit-scrollbar-thumb { background: rgba(148,163,184,0.35); border-radius: 10px; }
            .tx-panel-body::-webkit-scrollbar-thumb:hover { background: rgba(148,163,184,0.55); }

            /* توست - نفس شكل باقي الـpopups (surface + حدود بلون الحالة) */
            .tx-panel-toast {
                position: fixed; bottom: 30px; left: 50%; transform: translateX(-50%);
                display: flex; align-items: center; gap: 10px;
                background: var(--tx-surface-0);
                backdrop-filter: blur(16px) saturate(160%);
                -webkit-backdrop-filter: blur(16px) saturate(160%);
                border: 1px solid rgba(var(--tx-ok), 0.45);
                border-radius: var(--tx-radius-lg); padding: 10px 16px 10px 14px;
                width: max-content !important; max-width: min(92vw, 520px) !important; box-sizing: border-box !important;
                z-index: 300000; overflow: hidden;
                box-shadow: var(--tx-shadow-pop);
                direction: rtl; font-family: var(--tx-font); color: var(--tx-text);
                animation: tx-toast-spring 0.3s var(--tx-ease);
            }
            .tx-panel-toast.error { border-color: rgba(var(--tx-danger), 0.5); }
            @keyframes tx-toast-spring { from { transform: translate(-50%,18px) scale(0.96); opacity: 0; } to { transform: translate(-50%,0) scale(1); opacity: 1; } }
            .tx-toast-icon {
                width: 22px; height: 22px; border-radius: 50%; flex-shrink: 0;
                display: flex; align-items: center; justify-content: center; font-size: 12px;
                background: rgba(var(--tx-ok), 0.16); color: rgb(var(--tx-ok));
            }
            .tx-toast-icon .tx-emo { color: inherit; }
            .tx-panel-toast.error .tx-toast-icon { background: rgba(var(--tx-danger), 0.16); color: rgb(var(--tx-danger)); }
            .tx-toast-text-wrap { display: flex; flex-direction: column; align-items: center; text-align: center; line-height: 1.4; flex: 1 1 auto; min-width: 0; max-width: 100%; unicode-bidi: plaintext; }
            .tx-panel-toast .tx-toast-text-wrap, .tx-panel-toast .tx-toast-text-main, .tx-panel-toast .tx-toast-text-sub { text-align: center !important; }
            .tx-toast-icon.tx-toast-close { cursor: pointer; border: 0; padding: 0; font-family: inherit; transition: background .15s var(--tx-ease), transform .15s var(--tx-ease); }
            .tx-toast-icon.tx-toast-close:hover { background: rgba(var(--tx-danger), 0.35); transform: scale(1.12); }
            .tx-panel-toast { cursor: default; }
            .tx-toast-text-main { color: #fff; font-weight: 700; font-size: 12.5px; white-space: normal; overflow-wrap: anywhere; max-width: 100%; }
            .tx-toast-num { color: rgb(var(--tx-ok)); font-weight: 800; }
            .tx-panel-toast.error .tx-toast-num { color: rgb(var(--tx-danger)); }
            .tx-toast-text-sub { color: var(--tx-text-dim); font-size: 0.85em; margin-top: 2px; white-space: normal; overflow-wrap: anywhere; max-width: 100%; }
            .tx-toast-progress {
                position: absolute; bottom: 0; right: 0; height: 2px; width: 100%;
                background: rgb(var(--tx-ok)); animation: tx-toast-shrink 2.6s linear forwards;
            }
            .tx-panel-toast.error .tx-toast-progress { background: rgb(var(--tx-danger)); }
            @keyframes tx-toast-shrink { from { width: 100%; } to { width: 0%; } }
            @media (prefers-reduced-motion: reduce) {
                .tx-panel-overlay, .tx-panel-box, .tx-panel-toast, .tx-panel-badge.pulse { animation: none; }
                .tx-panel-btn, .tx-panel-item { transition: none; }
            }
        `;
        document.head.appendChild(style);
    }

    // ==================== (v28.19) بوب-أب تأكيد مخصص بدل confirm() الافتراضي بتاع المتصفح ====================
    // شكل confirm()/alert() الافتراضي بتاع المتصفح (اللي بيظهر بعنوان زي "123.60.141.64:10016 says")
    // غريب بصرياً ومالوش أي علاقة بستايل الأداة (Glassmorphism بنفسجي غامق، فونت Cairo، RTL) - بيبان
    // "مقحم" وسط باقي البوب-أبات التانية. الدالة دي بتدّي نفس تجربة confirm() (بتوقف التنفيذ فعلياً
    // لحد ما يختار المستخدم، وبترجع true/false) لكن بستايل الأداة نفسه بالظبط - بتستخدم نفس كلاسات
    // .tx-panel-* الموجودة أصلاً (Header/Body/زراير)، فمفيش CSS جديد إلا القليل الخاص بحجم/تخطيط
    // بوب-أب التأكيد الأصغر (ensureConfirmModalStyles تحت) + زرار .danger واحد إضافي للعمليات الخطيرة.
    //
    // بترجع Promise<boolean> عشان تتستخدم بـ"await showConfirmModal(...)" زي أي async عادي - أي مكان
    // تاني في الأداة محتاج تأكيد (دلوقتي أو مستقبلاً) يقدر يستخدمها بدل ما يبني نفس المنطق من الأول.
    function ensureConfirmModalStyles() {
        if (document.getElementById('tx-confirm-modal-style')) return;
        const style = document.createElement('style');
        style.id = 'tx-confirm-modal-style';
        style.textContent = `

            .tx-confirm-box { width: 440px; }
            .tx-confirm-body {
                padding: 6px 18px 18px; color: var(--tx-text); font-size: 13.5px; line-height: 1.9;
                white-space: pre-line;
            }
            .tx-confirm-footer {
                display: flex; justify-content: flex-end; gap: 10px;
                padding: 12px 14px; border-top: 1px solid var(--tx-border);
            }
            .tx-confirm-footer .tx-panel-btn { padding: 8px 18px; font-size: 12.5px; }
        `;
        document.head.appendChild(style);
    }

    // opts: { icon, title, message, confirmText, cancelText, danger }
    function showConfirmModal(opts) {
        ensurePanelStyles();
        ensureConfirmModalStyles();

        return new Promise((resolve) => {
            const overlay = document.createElement('div');
            overlay.className = 'tx-panel-overlay';

            const box = document.createElement('div');
            box.className = 'tx-panel-box tx-confirm-box';

            const header = document.createElement('div');
            header.className = 'tx-panel-header';
            const titleDiv = document.createElement('div');
            titleDiv.className = 'tx-panel-title';
            titleDiv.textContent = (opts.icon || '⚠️') + ' ' + opts.title;
            header.appendChild(titleDiv);

            const body = document.createElement('div');
            body.className = 'tx-confirm-body';
            body.textContent = opts.message || '';

            const footer = document.createElement('div');
            footer.className = 'tx-confirm-footer';

            const cancelBtn = document.createElement('button');
            cancelBtn.className = 'tx-panel-btn';
                cancelBtn.textContent = opts.cancelText || 'إلغاء';

            const confirmBtn = document.createElement('button');
            confirmBtn.className = 'tx-panel-btn ' + (opts.danger ? 'danger' : 'fix');
            confirmBtn.textContent = opts.confirmText || 'تأكيد';

            function close(result) {
                document.removeEventListener('keydown', escHandler);
                overlay.remove();
                resolve(result);
            }
            function escHandler(e) {
                if (e.key === 'Escape') close(false);
            }

            overlay.onclick = (e) => { if (e.target === overlay) close(false); };
            cancelBtn.onclick = () => close(false);
            confirmBtn.onclick = () => close(true);
            document.addEventListener('keydown', escHandler);

            footer.appendChild(cancelBtn);
            footer.appendChild(confirmBtn);
            box.appendChild(header);
            box.appendChild(body);
            box.appendChild(footer);
            overlay.appendChild(box);
            document.body.appendChild(overlay);
            confirmBtn.focus();
        });
    }

    function escapeHtml(str) {
        return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }

    function highlightNumbers(text) {
        return text.replace(/\d+(\.\d+)?/g, m => '<span class="tx-panel-num">' + m + '</span>');
    }

    function classifyItem(text) {
        if (/✅/.test(text)) return 'ok';
        if (/(🚫|❌|⏱️|🔗|🔢|✏️|٪|📐|#️⃣|🔤|📏|⚪)/.test(text)) return 'warn';
        return 'info';
    }

    // ==================== هايلايت السيجمنتات - Soft Glowing Outline (v12.0) ====================
    function ensureRowHighlightStyles() {
        if (document.getElementById('tx-row-highlight-style')) return;
        const style = document.createElement('style');
        style.id = 'tx-row-highlight-style';
        style.textContent = `
            tr.tx-row-error, tr.tx-row-ok, tr.tx-row-warn {
                outline-offset: -1px;
                border-radius: 8px;
                transition: outline-color 0.25s ease, background-color 0.3s ease;
            }
            tr.tx-row-error {
                outline: 1.5px solid rgba(239, 68, 68, 0.55) !important;
                background-color: rgba(239, 68, 68, 0.045) !important;
            }
            tr.tx-row-warn {
                outline: 1.5px solid rgba(234, 179, 8, 0.55) !important;
                background-color: rgba(234, 179, 8, 0.045) !important;
            }
            tr.tx-row-ok {
                outline: 1.5px solid rgba(34, 197, 94, 0.55) !important;
                background-color: rgba(34, 197, 94, 0.045) !important;
                animation: tx-row-ok-fade 4s ease forwards;
            }
            @keyframes tx-row-ok-fade {
                0% { outline-color: rgba(34,197,94,0.75); background-color: rgba(34,197,94,0.07); }
                100% { outline-color: rgba(34,197,94,0.2); background-color: rgba(34,197,94,0.01); }
            }

            .tx-save-dot {
                display: inline-block; width: 7px; height: 7px; border-radius: 50%;
                margin-inline-start: 6px; vertical-align: middle;
                background: #64748b;
                transition: background 0.25s ease, box-shadow 0.25s ease;
            }
            .tx-save-dot.tx-dot-typing {
                background: #eab308; box-shadow: 0 0 6px rgba(234,179,8,0.7);
                animation: tx-dot-pulse 1s ease-in-out infinite;
            }
            .tx-save-dot.tx-dot-saved {
                background: #22c55e; box-shadow: 0 0 6px rgba(34,197,94,0.6);
            }
            @keyframes tx-dot-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }
        `;
        document.head.appendChild(style);
    }
    ensureRowHighlightStyles();

    function setRowStatus(row, status) {
        row.style.outline = '';
        row.classList.remove('tx-row-error', 'tx-row-warn', 'tx-row-info', 'tx-row-ok');
        // (v29.32.5) كل المشاكل لون واحد (أحمر): أي 'warn' أو 'info' بيتعامل كـ'error'
        if (status === 'error' || status === 'warn' || status === 'info') row.classList.add('tx-row-error');
        else if (status === 'ok') row.classList.add('tx-row-ok');
    }

    // (v29.32.5) كل رسائل المشاكل بنفس الخطورة (أحمر) - طول الحروف والمسافات والإنجليزي والتشكيل كلها strict
    function txMsgSeverity(msg) { return 'error'; }

    // ==================== اختصارات كيبورد لإضافة تاج الـ Attribute وانت جوه السيجمنت (v22.0) ====================
    // Alt+1/2/3/4 بيحاكي ضغطة ماوس حقيقية على خيار التاج في بانل/بوب-أب "Attribute" بتاع الموقع نفسه
    // (مش بينده على أي دالة داخلية للموقع) - فـ Vue بتاعة الموقع هي اللي بتطبّق التاج على السيجمنت اللي
    // إنت فوكس/بتكتب فيه دلوقتي بالظبط، لأن الموقع بيحدد "السيجمنت الحالي" أوتوماتيك لحظة ما تدخل تكتب فيه.
    // ملحوظة (v21.0): كانت Ctrl+Alt+رقم، اتغيّرت لـ Alt+رقم بس - أسهل في الضغط، ومفيش تعارض معروف بيها
    // مع اختصارات ويندوز أو كروم (زي Alt+V المستخدم فعلاً لحافظة النصوص). الترتيب: 1=NOISE، 2=DEAF،
    // 3=OOV، 4=OVERLAP.
    // ملحوظة (v22.0): "شيل التاج" كان Alt+0 - إيدك بتتمدد بعيد لرقم 0 كل مرة، فاتغيّر لـ Alt+X (X جنب
    // الرقم/الحروف اللي إنت أصلاً بتستخدمها، مفيش تعارض معروف بيه في المتصفحات أو ويندوز، وسهل في الضغط).
    const ATTR_TAG_SHORTCUTS = {
        'Digit1': '<NOISE>',
        'Digit2': '<DEAF>',
        'Digit3': '<OOV>',
        'Digit4': '<OVERLAP>'
    };

    // (v23.0) أحياناً حد بيكتب تاج زي <DEAF> أو <NOISE> كنص عادي جوه مربع الكتابة (مش عن طريق بانل
    // الـAttribute الحقيقي) - وده بيظهر كـ"تاج شكلي" في الفحص الحي بس فعلياً هو مجرد كلام. Alt+X كان
    // بيشيل التاج الحقيقي (الـpill) بس مش بيلمس التاج المكتوب كنص. هنا بنستهدف التاجات الأربعة دي
    // بالظبط (مش أي كلام تاني) عشان لو اتكتبوا كنص، Alt+X يشيلهم زيهم زي الـpill بالظبط.
    const TEXT_TAG_TOKEN_REGEX = /<\s*(?:NOISE|DEAF|OOV|OVERLAP)\s*>/gi;

    // ملحوظة مهمة: البانل ده بيتفتح في الموقع الأصلي بالهوفر الحقيقي بالماوس (CSS :hover) بس - وده حاجة
    // الجافاسكريبت مش قادرة تحاكيها (dispatch لحدث mouseenter/mouseover مش بيغيّر حالة :hover الحقيقية).
    // فالعنصر بيفضل display:none (offsetParent = null) لحد ما تحصل هوفر حقيقي. الحل: مش محتاجين العنصر
    // يبقى ظاهر بصرياً أصلاً - أي حدث click متبعوت بـ dispatchEvent بيشغّل الـ listener المربوط بالعنصر
    // عادي حتى لو كان مخفي بالكامل (display:none)، لأن ده استدعاء مباشر للـ listener مش محاكاة حقيقية
    // للماوس محتاجة hit-testing بصري. فبنلاقي العنصر بس (من غير شرط ظهور) وندوس عليه مباشرة.
    // بيرجع الصف (tr) بتاع السيجمنت اللي إنت واقف جواه دلوقتي (الـ textarea اللي عليها الفوكس) -
    // ده اللي بيضمن إننا نطبّق التاج على السيجمنت الصح بالظبط، مش أي حاجة تانية شكلها زيها في الصفحة.
    function getActiveSegmentRow() {
        const active = document.activeElement;
        return active ? active.closest('tr') : null;
    }

    // بندوّر جوه صف السيجمنت الحالي بس أول حاجة (لو خلية الـ Attribute موجودة فعلاً جواه) - ده بيقلل
    // احتمال إننا نلقط نسخة تخص صف تاني. لو مفيش نتيجة (زي لو البانل بتاع الموقع بيتعمله teleport
    // لبرة الجدول لـ document.body)، بنرجع نبحث في الصفحة كلها كـ fallback - لكن (v22.0) الـfallback
    // ده كان بيرجّع أول عنصر في ترتيب الـDOM من غير ما يتأكد إنه فعلاً بتاع صف السيجمنت الحالي، وده
    // كان بيسبب "التاج بيتطبق عشوائي على سيجمنت تاني" لو فيه نسخ "شبح" متكررة في الصفحة. دلوقتي
    // findAttrTagOptions لسه بترجع كل النسخ زي ما هي، بس اللي بيستخدمها (pickBestTagOption) هو
    // اللي بيفضّل النسخة المتأكد إنها جوه scopeRow قبل ما ياخد أي نسخة تانية.
    function findAttrTagOptions(tagTitle, scopeRow) {
        const scope = scopeRow ? scopeRow.querySelector('.attr') : null;
        if (scope) {
            const scoped = scope.querySelectorAll('.labelList span.text[title="' + tagTitle + '"]');
            if (scoped.length > 0) return scoped;
        }
        return document.querySelectorAll('.labelList span.text[title="' + tagTitle + '"]');
    }

    // بيختار من كل النسخ المطابقة (جايه من findAttrTagOptions) النسخة اللي فعلاً جوه صف السيجمنت
    // الحالي (row.contains) لو موجودة - وده بيضمن إننا منطبقش على نسخة "شبح" بتاعة صف تاني حتى لو
    // fallback البحث في الصفحة كلها رجّع أكتر من نتيجة. لو مفيش ولا نسخة مؤكدة جوه الصف، بناخد أول
    // نتيجة زي القديم (أحسن من عدم التطبيق خالص، بس الأولوية دايماً للنسخة المؤكدة).
    function pickBestTagOption(spans, row) {
        if (!spans || spans.length === 0) return null;
        if (row) {
            const contained = Array.from(spans).find(s => row.contains(s));
            if (contained) return contained;
        }
        return spans[0];
    }

    // (v23.0) الجزء الفعلي من تطبيق التاج على صف بعينه، مستقل عن "الصف المتفوكس عليه دلوقتي" - ده اللي
    // بيسمح لنفس المنطق يتستخدم في اختصار Alt+رقم العادي (على السيجمنت الحالي) وكمان في التطبيق الدفعي
    // (Batch) على مجموعة صفوف محددة مرة واحدة، من غير تكرار كود. بيرجّع true/false على حسب لو فعلاً
    // اتطبّق حاجة، عشان اللي بينادي عليه (batch) يقدر يعد كام صف نجح فعلاً.
    async function applyAttrTagToRow(row, tagTitle, opts) {
        const silent = !!(opts && opts.silent);
        const rowInfo = getRowInfo(row);
        const serial = rowInfo.serial;
        const beforeTags = rowInfo.attrTagTexts.filter(Boolean);

        if (beforeTags.length === 1 && beforeTags[0] === tagTitle) {
            if (!silent) showToast('السيجمنت أصلاً عليه تاج ' + tagTitle + ' ✅');
            return false;
        }

        const oldTags = beforeTags.filter(t => t && t !== tagTitle);
        if (oldTags.length > 0) {
            oldTags.forEach(oldTag => {
                const match = pickBestTagOption(findAttrTagOptions(oldTag, row), row);
                if (match) match.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true }));
            });
            await sleep(120);
        }

        const spans = findAttrTagOptions(tagTitle, row);
        const match = pickBestTagOption(spans, row);
        if (!match) {
            if (!silent) showToast('معرفتش ألاقي خيار التاج "' + tagTitle + '" في الصفحة خالص - يمكن شكل البانل اتغيّر في تحديث للموقع', true);
            return false;
        }
        match.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true }));
        if (!silent) showToast((oldTags.length > 0 ? 'تم استبدال التاج بـ ' : 'تم تطبيق تاج ') + tagTitle + ' ⌨️');
        pushTagUndoStep(serial, beforeTags, [tagTitle], 'تاج ' + tagTitle);
        return true;
    }

    async function applyAttrTagShortcut(tagTitle) {
        const row = getActiveSegmentRow();
        // (v22.0) لو مفيش سيجمنت متفوكس عليه دلوقتي (يعني مش واقف جوه textarea سيجمنت)، منطبقش على
        // أي حاجة خالص - قبل كده كان بيدور على أول نسخة في الصفحة كلها ويطبّق عليها "عشوائي" حتى لو
        // إنت مش واقف في أي سيجمنت، وده بالظبط اللي كنت بتشتكي منه.
        if (!row) {
            showToast('دوس جوه مربع كتابة السيجمنت الأول عشان الاختصار يعرف يطبّق على انهي سيجمنت بالظبط', true);
            return;
        }
        // ملحوظة مهمة (v17.7.2): كنا فاكرين إن بعت الكليك لكل النسخ المطابقة آمن ("احتياطي" لو فيه
        // تكرار)، بس اتضح إن ده هو نفسه السبب في مشكلة "التاج مش بيتطبق": الموقع فعلاً عنده نسخة
        // "شبح" متكررة من نفس الخيار في الـDOM، وكل نسخة منهم بتنفّذ الـtoggle الحقيقي بنجاح - فكليكتين
        // معناهم: إضافة التاج فوراً متبوعة بشيله (toggle مرتين = رجوع لنفس الحالة)، فالنتيجة الظاهرة
        // إن مفيش حاجة اتغيّرت خالص. الحل: نبعت كليك واحد بس - للنسخة المؤكدة (أو الأولى لو مفيش مؤكدة).
        await applyAttrTagToRow(row, tagTitle);
    }

    // (v23.0) نفس فكرة applyAttrTagToRow بس للشيل - مستقل عن الصف المتفوكس عليه، عشان يتستخدم في
    // الشيل الدفعي (Batch) كمان.
    async function removeAttrTagFromRow(row, opts) {
        const silent = !!(opts && opts.silent);
        const rowInfo = getRowInfo(row);
        // (v28.21.10) صف مش سيجمنت حقيقي (spacer / صف تحميل / أي tr من غير رقم ومربع نص) بيرجّع null هنا - كان
        // بيرمي TypeError بيوقف أي عملية جماعية (زي تفريغ الكل) في نص الطريق.
        if (!rowInfo) return false;
        const serial = rowInfo.serial;
        const existingTags = rowInfo.attrTagTexts.filter(Boolean);
        const removedTextTag = stripLiteralTagTextFromRow(row);

        if (existingTags.length === 0 && !removedTextTag) return false;

        if (existingTags.length > 0) {
            existingTags.forEach(tag => {
                const match = pickBestTagOption(findAttrTagOptions(tag, row), row);
                if (match) match.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true }));
            });
            pushTagUndoStep(serial, existingTags, [], 'شيل التاج');
        }

        if (!silent) {
            if (existingTags.length > 0 && removedTextTag) showToast('تم شيل تاج الـAttribute وكمان التاج المكتوب كنص 🗑️');
            else if (removedTextTag) showToast('تم شيل التاج المكتوب كنص من السيجمنت 🗑️');
            else showToast('تم شيل التاج من السيجمنت 🗑️');
        }
        return true;
    }

    // Alt+X (كان Alt+0 قبل v22.0) - بيشيل أي تاج Attribute موجود على السيجمنت الحالي خالص، من غير ما
    // يحط بدله تاج تاني. بيستخدم نفس آلية الـtoggle (كليك تاني على نفس خيار التاج بيشيله) لكل
    // التاجات الموجودة على السيجمنت (ممكن يبقوا أكتر من واحد متكدسين لو حصل خطأ سابق).
    // بيشيل أي تاج من التاجات الأربعة (NOISE/DEAF/OOV/OVERLAP) لو اتكتب كنص عادي جوه textarea
    // السيجمنت، من غير ما يلمس أي كلام تاني. بيستخدم setNativeFieldValue عشان الموقع (Vue) يحس
    // بالتغيير زي أي كتابة عادية - وده كمان بيخليه يتسجل لوحده في نظام تراجع التعديلات النصية
    // العادي (initEditTracking بيسمع لحدث 'input') من غير داعي لتعامل خاص.
    function stripLiteralTagTextFromRow(row) {
        const textarea = row.querySelector('.textContent .mark-content-textarea');
        if (!textarea) return false;
        const before = textarea.value !== undefined ? textarea.value : textarea.textContent;
        if (!before) return false;
        TEXT_TAG_TOKEN_REGEX.lastIndex = 0;
        if (!TEXT_TAG_TOKEN_REGEX.test(before)) return false;
        TEXT_TAG_TOKEN_REGEX.lastIndex = 0;
        let after = before.replace(TEXT_TAG_TOKEN_REGEX, '');
        // تنضيف المسافات الزيادة اللي ممكن تفضل مكان التاج اللي اتشال (زي مسافتين ورا بعض أو مسافة في الأول/الآخر)
        after = after.replace(/\s{2,}/g, ' ').replace(/^\s+|\s+$/g, '');
        if (after === before) return false;
        setNativeFieldValue(textarea, after);
        return true;
    }

    async function removeAttrTagShortcut() {
        const row = getActiveSegmentRow();
        if (!row) {
            showToast('دوس جوه مربع كتابة السيجمنت الأول عشان الاختصار يعرف يشيل تاج انهي سيجمنت بالظبط', true);
            return;
        }
        const removed = await removeAttrTagFromRow(row);
        if (!removed) showToast('السيجمنت مفيهوش تاج Attribute ولا تاج مكتوب كنص');
    }

    // ==================== (v26.0) نقل كلام السيجمنت للسيجمنت اللي تحته - Alt+N ====================
    // اختصار جديد ملوش علاقة بالتاجات خالص (بعكس Alt+X اللي بيشيل التاج بس) - وظيفته إنه ياخد كل كلام
    // السيجمنت الحالي (اللي إنت واقف جواه) وينقله بالكامل للسيجمنت اللي تحته مباشرة، بدل ما يمسحه للأبد.
    // شرطين لازم يتحققوا الاثنين مع بعض قبل ما يعمل أي حاجة: (1) السيجمنت الحالي فيه كلام أصلاً (مفيش
    // معنى تنقل فراغ)، (2) السيجمنت اللي تحته لازم يكون فاضي بالكامل - لو فيه كلام بالفعل، بننبّهك
    // ومنعملش النقل خالص عشان منمسحش كلامه (زي ما طلبت بالظبط).
    async function moveSegmentTextToNextRow() {
        const row = getActiveSegmentRow();
        if (!row) {
            showToast('دوس جوه مربع كتابة السيجمنت الأول عشان الاختصار يعرف ينقل كلام انهي سيجمنت بالظبط', true);
            return;
        }
        const nextRow = row.nextElementSibling;
        if (!nextRow || nextRow.tagName !== 'TR') {
            showToast('مفيش سيجمنت تحت السيجمنت الحالي (يمكن ده آخر سيجمنت في الصفحة)', true);
            return;
        }

        const curTextarea = row.querySelector('.textContent .mark-content-textarea');
        const nextTextarea = nextRow.querySelector('.textContent .mark-content-textarea');
        if (!curTextarea || !nextTextarea) {
            showToast('معرفتش ألاقي مربع كتابة السيجمنت الحالي أو اللي تحته - يمكن شكل الصفحة اتغيّر', true);
            return;
        }

        const curValue = curTextarea.value !== undefined ? curTextarea.value : curTextarea.textContent;
        if (!curValue || !curValue.trim()) {
            showToast('السيجمنت الحالي فاضي أصلاً - مفيش كلام ننقله', true);
            return;
        }

        const nextValue = nextTextarea.value !== undefined ? nextTextarea.value : nextTextarea.textContent;
        if (nextValue && nextValue.trim()) {
            showToast('⚠️ السيجمنت اللي تحت فيه كلام بالفعل - لن يتم النقل عليه تجنّباً لمسح كلامه. يجب إفراغه أولاً لإتمام النقل', true);
            return;
        }

        // بنلف العملية في runBatchOperation عشان تتسجل كخطوة تراجع واحدة (مش اتنين منفصلتين) - Ctrl+Z
        // واحدة ترجع الاتنين مع بعض (تاخد الكلام رجوع من تحت وترجعه فوق تاني) بدل ما تحتاج ضغطتين.
        await runBatchOperation('نقل كلام سيجمنت للي تحته', async () => {
            setNativeFieldValue(nextTextarea, curValue);
            setNativeFieldValue(curTextarea, '');
        });

        showToast('تم نقل كلام السيجمنت للسيجمنت اللي تحته ✂️➡️');
        // بننقل الفوكس للسيجمنت اللي استقبل الكلام - استكمال طبيعي لسير الشغل (نزلت سيجمنت، وقفت جوه اللي بعده)
        try {
            nextTextarea.focus();
            const pos = nextTextarea.value.length;
            nextTextarea.selectionStart = nextTextarea.selectionEnd = pos;
        } catch (e) { /* تجاهل */ }
    }

    // ==================== Command Palette موحّد - Alt+K (v23.0) ====================
    // بيجمع كل أزرار القائمة العائمة (زرار زرار زي ما هو موجود فعلاً بنصه وإيموجيه) + كام أمر إضافي
    // (تشغيل/إيقاف الإصلاح التلقائي أثناء الكتابة، تنظيف مساحة التخزين) في مكان واحد بحث نصي، بدل
    // ما تدوّر عليهم بالعين جوه القائمة العائمة. بيشتغل بالكليك على أي زرار حقيقي (btn.click())
    // فمفيش تكرار منطق - أي زرار جديد يتضاف في القائمة العائمة هيظهر هنا أوتوماتيك.
    function ensureCommandPaletteStyles() {
        if (document.getElementById('tx-cmdk-style')) return;
        const style = document.createElement('style');
        style.id = 'tx-cmdk-style';
        style.textContent = `
            .tx-cmdk-box { width: 520px; }
            .tx-cmdk-input-wrap { padding: 12px 14px; border-bottom: 1px solid rgba(255,255,255,0.08); }
            .tx-cmdk-input {
                width: 100%; box-sizing: border-box; background: rgba(255,255,255,0.07);
                border: 1px solid rgba(255,255,255,0.16); border-radius: 10px; padding: 10px 12px;
                color: #fff; font-family: 'Cairo', 'Segoe UI', Tahoma, sans-serif; font-size: 13.5px;
                direction: rtl; outline: none;
            }
            .tx-cmdk-input:focus { border-color: rgba(var(--tx-accent),0.6); }
            .tx-cmdk-input::placeholder { color: rgba(255,255,255,0.4); }
            .tx-cmdk-list { max-height: 55vh; overflow-y: auto; padding: 6px; }
            .tx-cmdk-item {
                display: flex; align-items: center; padding: 10px 12px; border-radius: 10px;
                cursor: pointer; color: #e2e8f0; font-size: 13px;
                font-family: 'Cairo', 'Segoe UI', Tahoma, sans-serif;
            }
            .tx-cmdk-item:hover, .tx-cmdk-item.tx-cmdk-active { background: rgba(var(--tx-accent),0.25); color: #fff; }
            .tx-cmdk-empty { padding: 24px; text-align: center; color: rgba(255,255,255,0.4); font-size: 13px; }
        `;
        document.head.appendChild(style);
    }

    function getCommandPaletteEntries() {
        const entries = [];
        const seen = new Set();
        document.querySelectorAll('.tx-tool-btn').forEach(btn => {
            const label = (btn.dataset.txLabel || btn.textContent || '').trim();
            if (!label || seen.has(label)) return; // منمنعش تكرار (زرار ممكن يبقى معاد ترتيبه في القائمة)
            seen.add(label);
            entries.push({ label, run: () => btn.click() });
        });
        entries.push({
            label: (liveAutoFixEnabled ? '🛑 إيقاف' : '✅ تشغيل') + ' الإصلاح التلقائي أثناء الكتابة',
            run: toggleLiveAutoFix
        });
        entries.push({ label: '✂️➡️ نقل كلام السيجمنت الحالي للي تحته (Alt+N)', run: moveSegmentTextToNextRow });
        entries.push({ label: (breakState ? '⏹ إنهاء البريك' : '☕ بدء بريك') + ' (Alt+B)', run: toggleBreak });
        entries.push({ label: shiftState ? '🏁 إنهاء الشيفت' : '🕘 بدء الشيفت', run: toggleShift });
        entries.push({ label: '🧹 تنظيف مساحة التخزين المحلية للأداة', run: () => runTxStorageCleanup(true) });
        entries.push({ label: '📊 عرض حجم التخزين المستخدم', run: showTxStorageUsageToast });
        return entries;
    }

    function showCommandPalette() {
        ensurePanelStyles();
        ensureCommandPaletteStyles();

        const allEntries = getCommandPaletteEntries();
        const overlay = document.createElement('div');
        overlay.className = 'tx-panel-overlay';
        overlay.onclick = (e) => { if (e.target === overlay) close(); };

        const box = document.createElement('div');
        box.className = 'tx-panel-box tx-cmdk-box';

        const inputWrap = document.createElement('div');
        inputWrap.className = 'tx-cmdk-input-wrap';
        const input = document.createElement('input');
        input.className = 'tx-cmdk-input';
        input.type = 'text';
        input.placeholder = 'دوّر على أي زرار أو أمر... (اكتب واختار بالسهم + Enter)';
        inputWrap.appendChild(input);

        const list = document.createElement('div');
        list.className = 'tx-cmdk-list';

        let activeIndex = 0;
        let filtered = allEntries;
        let itemElements = [];

        // (v24.0) قبل كده render() كانت بتمسح كل الـDOM (innerHTML = '') وتبنيه من جديد مع كل ضغطة
        // سهم أو حتى كل مرة الماوس يعدي فوق عنصر - وده كان بيصفّر سكرول القائمة لفوق تلقائي كل مرة
        // (المتصفح بيصفّر scrollTop لما تمسح محتوى عنصر) فكان شكله "بيحدد بس مش بيتحرك السكرول معاه"،
        // وكمان بيسبب و ميض غريب تحت الماوس وهي واقفة في مكانها. دلوقتي البناء الكامل بيحصل مرة واحدة
        // بس (أول ما تفتح القائمة أو لما نتيجة البحث تتغيّر)، وتغيير التحديد (سواء بالسهم أو بالماوس)
        // بيغيّر كلاس العنصر النشط بس من غير ما يلمس باقي الـDOM، فالسكرول بتاع المتصفح فعلياً بيفضل
        // زي ما هو.
        function render() {
            list.innerHTML = '';
            itemElements = [];
            if (filtered.length === 0) {
                const empty = document.createElement('div');
                empty.className = 'tx-cmdk-empty';
                empty.textContent = 'مفيش نتائج مطابقة 🤷';
                list.appendChild(empty);
                return;
            }
            filtered.forEach((entry, i) => {
                const item = document.createElement('div');
                item.className = 'tx-cmdk-item' + (i === activeIndex ? ' tx-cmdk-active' : '');
                item.textContent = entry.label;
                item.onmouseenter = () => setActiveIndex(i, false);
                item.onclick = () => run(entry);
                list.appendChild(item);
                itemElements.push(item);
            });
        }

        function setActiveIndex(i, shouldScroll) {
            if (itemElements[activeIndex]) itemElements[activeIndex].classList.remove('tx-cmdk-active');
            activeIndex = i;
            const el = itemElements[activeIndex];
            if (el) {
                el.classList.add('tx-cmdk-active');
                if (shouldScroll) el.scrollIntoView({ block: 'nearest' });
            }
        }

        function run(entry) {
            close();
            entry.run();
        }

        function close() {
            overlay.remove();
            document.removeEventListener('keydown', keyHandler, true);
        }

        function keyHandler(e) {
            if (e.key === 'Escape') { e.preventDefault(); close(); return; }
            if (e.key === 'ArrowDown') { e.preventDefault(); setActiveIndex(Math.min(activeIndex + 1, filtered.length - 1), true); return; }
            if (e.key === 'ArrowUp') { e.preventDefault(); setActiveIndex(Math.max(activeIndex - 1, 0), true); return; }
            if (e.key === 'Enter') { e.preventDefault(); if (filtered[activeIndex]) run(filtered[activeIndex]); return; }
        }

        input.addEventListener('input', () => {
            const q = input.value.trim().toLowerCase();
            filtered = q ? allEntries.filter(e => e.label.toLowerCase().includes(q)) : allEntries;
            activeIndex = 0;
            render();
        });
        document.addEventListener('keydown', keyHandler, true);

        render();
        box.appendChild(inputWrap);
        box.appendChild(list);
        overlay.appendChild(box);
        document.body.appendChild(overlay);
        setTimeout(() => input.focus(), 30);
    }

    // ==================== نقطة الحفظ التلقائي (Smart Auto-Save Indicator) (v12.0) ====================
    function getOrCreateSaveDot(row) {
        const numberCell = row.querySelector('.number');
        if (!numberCell) return null;
        let dot = numberCell.querySelector('.tx-save-dot');
        if (!dot) {
            dot = document.createElement('span');
            dot.className = 'tx-save-dot';
            numberCell.appendChild(dot);
        }
        return dot;
    }

    function setSaveDotState(row, state) {
        const dot = getOrCreateSaveDot(row);
        if (!dot) return;
        dot.classList.remove('tx-dot-typing', 'tx-dot-saved');
        if (state === 'typing') dot.classList.add('tx-dot-typing');
        else if (state === 'saved') dot.classList.add('tx-dot-saved');
    }

    // (v28.21.8) النسبة المئوية: مكان علامة ％ المتخزّن بيتحدد حسب "أقرب حرف قوي" قبل الرقم في السيجمنت -
    // ده اللي بيقرره خوارزمية الـBidi بتاعة المتصفح (قاعدة W2): لو أقرب حرف قبل الرقم عربي، الرقم بيتعامل كرقم
    // عربي (AN) والعلامة بتتزاح على الشمال بصرياً، فبنخزّن "100％" ويبان "％100". أما لو مفيش حرف عربي قبله
    // (أول السيجمنت، أو بعد إنجليزي/تاج زي <NOISE>) الرقم بيفضل رقم عادي (EN) والترتيب المتخزّن هو نفسه اللي
    // بيبان، فبنخزّن "％100" ويبان "％100". الهدف الثابت: على الشاشة العلامة دايماً على شمال الرقم.
    function percentSignBeforeNumberStored(str, idx) {
        for (let i = idx - 1; i >= 0; i--) {
            const c = str[i];
            if (/[\u0621-\u064A\u066E-\u06D3\u06FA-\u06FF\u0750-\u077F\uFB50-\uFDFF\uFE70-\uFEFF]/.test(c)) return false; // عربي ⬅️ "رقم％"
            if (/[A-Za-z\u00C0-\u024F\u05D0-\u05EA]/.test(c)) return true; // لاتيني/عبري ⬅️ "％رقم"
        }
        return true; // مفيش حرف قوي قبله ⬅️ "％رقم"
    }


    // (v28.21.11) علم "عملية جماعية شغالة" (زي تفريغ كل السيجمنتات): وقتها الفحص الحي (input + MutationObserver +
    // الفحص الدوري) بيقف مؤقتاً، لأن كل صف بيتفرّغ كان بيشغّل تقييم كامل + إعادة رسم ماركرز الأخطاء على كل الصفوف
    // - وده كان سبب اللاج. بمجرد ما العملية تخلص بنعمل فحص واحد بس للصفوف الظاهرة.
    let txBulkBusy = false;

    function showToast(message, isError, durationMs) {
        const duration = durationMs || 2600;
        ensurePanelStyles();
        const toast = document.createElement('div');
        toast.className = 'tx-panel-toast' + (isError ? ' error' : '');

        const icon = document.createElement('span');
        icon.className = 'tx-toast-icon';
        icon.textContent = isError ? '✕' : '✓';
        let dismissTimer = null;
        const dismissToast = () => { clearTimeout(dismissTimer); toast.remove(); };
        // (v29.5) علامة ✕/✓ بقت زرار قفل شغّال: دوس عليها (أو على التوست نفسه) يخفيه فوراً
        icon.classList.add('tx-toast-close');
        icon.title = 'إخفاء';
        icon.addEventListener('click', (ev) => { ev.stopPropagation(); dismissToast(); });
        toast.addEventListener('click', dismissToast);

        const textWrap = document.createElement('div');
        textWrap.className = 'tx-toast-text-wrap';

        const dashSplitIndex = message.indexOf(' - ');
        const mainText = dashSplitIndex === -1 ? message : message.slice(0, dashSplitIndex);
        const subText = dashSplitIndex === -1 ? '' : message.slice(dashSplitIndex + 3);

        const mainDiv = document.createElement('div');
        mainDiv.className = 'tx-toast-text-main';
        mainDiv.innerHTML = escapeHtml(mainText).replace(/\d+(\.\d+)?/g, m => '<span class="tx-toast-num">' + m + '</span>');
        textWrap.appendChild(mainDiv);

        if (subText) {
            const subDiv = document.createElement('div');
            subDiv.className = 'tx-toast-text-sub';
            subDiv.textContent = subText;
            textWrap.appendChild(subDiv);
        }

        const progress = document.createElement('div');
        progress.className = 'tx-toast-progress';
        progress.style.animationDuration = (duration / 1000) + 's';

        toast.appendChild(icon);
        toast.appendChild(textWrap);
        toast.appendChild(progress);
        document.body.appendChild(toast);
        dismissTimer = setTimeout(() => toast.remove(), duration);
    }

    function extractSerialFromString(str) {
        if (!str) return null;
        const m = String(str).match(/سيجمنت\s+(\d+)/);
        return m ? parseInt(m[1], 10) : null;
    }

    // ==================== كونفيرم زجاجي (بديل window.confirm البشع) (v15.0) ====================
    function ensureConfirmStyles() {
        if (document.getElementById('tx-confirm-style')) return;
        const style = document.createElement('style');
        style.id = 'tx-confirm-style';
        style.textContent = `

            .tx-confirm-box {
                width: 420px; max-width: 90vw;
                background: var(--tx-surface-0);
                backdrop-filter: blur(16px) saturate(160%);
                -webkit-backdrop-filter: blur(16px) saturate(160%);
                border: 1px solid rgba(var(--tx-accent), 0.3);
                border-radius: var(--tx-radius-lg);
                box-shadow: var(--tx-shadow-pop);
                font-family: var(--tx-font);
                direction: rtl; color: var(--tx-text);
                animation: tx-pop-in 0.18s var(--tx-ease);
                position: relative;
            }
            .tx-confirm-box:not(.tx-panel-box) { padding: 20px 20px 16px; }
            .tx-confirm-msg { font-size: 13.5px; line-height: 1.9; white-space: pre-line; margin-bottom: 18px; }
            .tx-confirm-actions { display: flex; justify-content: flex-end; gap: 10px; }
            .tx-confirm-btn {
                display: inline-flex; align-items: center; justify-content: center; gap: 6px;
                padding: 8px 18px; border-radius: var(--tx-radius-md); cursor: pointer;
                background: var(--tx-surface-1); border: 1px solid var(--tx-border); color: var(--tx-text);
                font: 700 12.5px var(--tx-font);
                transition: background 0.15s var(--tx-ease), border-color 0.15s var(--tx-ease), box-shadow 0.15s var(--tx-ease);
            }
            .tx-confirm-btn:hover { background: var(--tx-surface-2); border-color: rgba(var(--tx-accent), 0.65); }
            .tx-confirm-btn:focus-visible { outline: 2px solid rgba(var(--tx-accent), 0.85); outline-offset: 1px; }
            .tx-confirm-btn.ok { background: rgba(var(--tx-ok), 0.13); border-color: rgba(var(--tx-ok), 0.5); color: #bbf7d0; }
            .tx-confirm-btn.ok:hover { background: rgba(var(--tx-ok), 0.24); border-color: rgba(var(--tx-ok), 0.85); box-shadow: 0 0 10px rgba(var(--tx-ok), 0.35); }
            .tx-confirm-btn.danger { background: rgba(var(--tx-danger), 0.14); border-color: rgba(var(--tx-danger), 0.55); color: #fecaca; }
            .tx-confirm-btn.danger:hover { background: rgba(var(--tx-danger), 0.24); border-color: rgba(var(--tx-danger), 0.85); box-shadow: 0 0 10px rgba(var(--tx-danger), 0.35); }
            @media (prefers-reduced-motion: reduce) { .tx-confirm-box { animation: none; } .tx-confirm-btn { transition: none; } }
        `;
        document.head.appendChild(style);
    }

    // بيرجع Promise<boolean> - true لو دوس تأكيد، false لو دوس إلغاء أو برة الصندوق أو Escape
    function showGlassConfirm(message, options) {
        ensurePanelStyles();
        ensureConfirmStyles();
        return new Promise((resolve) => {
            const overlay = document.createElement('div');
            overlay.className = 'tx-panel-overlay';

            const box = document.createElement('div');
            box.className = 'tx-confirm-box';

            const msg = document.createElement('div');
            msg.className = 'tx-confirm-msg';
            msg.textContent = message;

            const actions = document.createElement('div');
            actions.className = 'tx-confirm-actions';

            const cancelBtn = document.createElement('button');
            cancelBtn.className = 'tx-confirm-btn cancel';
            cancelBtn.textContent = (options && options.cancelLabel) || 'إلغاء';

            const okBtn = document.createElement('button');
            okBtn.className = 'tx-confirm-btn ok';
            okBtn.textContent = (options && options.okLabel) || 'تأكيد';

            function cleanup(result) {
                overlay.remove();
                document.removeEventListener('keydown', escHandler);
                resolve(result);
            }
            function escHandler(e) { if (e.key === 'Escape') cleanup(false); }

            cancelBtn.onclick = () => cleanup(false);
            okBtn.onclick = () => cleanup(true);
            overlay.onclick = (e) => { if (e.target === overlay) cleanup(false); };
            document.addEventListener('keydown', escHandler);

            actions.appendChild(cancelBtn);
            actions.appendChild(okBtn);
            box.appendChild(msg);
            box.appendChild(actions);
            overlay.appendChild(box);
            document.body.appendChild(overlay);
            okBtn.focus();
        });
    }

    function buildItemElement(item, rawLinesArr, serial, closeOverlayFn) {
        const itemText = typeof item === 'string' ? item : item.text;
        const itemType = typeof item === 'string' ? classifyItem(itemText) : (item.type || classifyItem(itemText));
        const div = document.createElement('div');
        div.className = 'tx-panel-item ' + itemType;

        const textSpan = document.createElement('span');
        textSpan.className = 'tx-panel-item-text';
        textSpan.innerHTML = highlightNumbers(escapeHtml(itemText));

        const copyItemBtn = document.createElement('button');
        copyItemBtn.className = 'tx-item-copy';
        copyItemBtn.textContent = '📋 نسخ';
        copyItemBtn.title = 'نسخ السطر ده بس';
        copyItemBtn.onclick = (e) => {
            e.stopPropagation();
            const ok = fallbackCopy(itemText);
            showToast(ok ? 'تم نسخ السطر ✅' : 'فشل النسخ ❌', !ok);
        };

        if (typeof serial === 'number' && !isNaN(serial)) {
            div.classList.add('jumpable');
            div.title = 'الضغط للانتقال لهذا السيجمنت وتشغيله في المشغل';
            div.onclick = () => {
                if (closeOverlayFn) closeOverlayFn();
                jumpToSegment(serial);
            };
        }

        div.appendChild(textSpan);
        div.appendChild(copyItemBtn);
        if (rawLinesArr) rawLinesArr.push(itemText);
        return div;
    }

    // sections: [{ heading: 'نص العنوان' أو null, items: ['نص' أو {text, type}] }]
    function showResultsPanel(title, sections, emptyMessage, extraAction, extraButtons) {
        ensurePanelStyles();

        const totalItems = sections.reduce((sum, s) => sum + s.items.length, 0);

        const overlay = document.createElement('div');
        overlay.className = 'tx-panel-overlay';
        overlay.onclick = (e) => { if (e.target === overlay) overlay.remove(); };

        const box = document.createElement('div');
        box.className = 'tx-panel-box';

        const header = document.createElement('div');
        header.className = 'tx-panel-header';

        const titleDiv = document.createElement('div');
        titleDiv.className = 'tx-panel-title';
        titleDiv.innerHTML = title + (totalItems > 0 ? ' <span class="tx-panel-badge pulse">' + totalItems + '</span>' : '');

        const actionsDiv = document.createElement('div');
        actionsDiv.className = 'tx-panel-actions';

        let fixBtn = null;
        if (extraAction && totalItems > 0) {
            fixBtn = document.createElement('button');
            fixBtn.className = 'tx-panel-btn ' + (extraAction.tone || 'fix');
            fixBtn.textContent = extraAction.label || '🔧 تصليح تلقائي';
            actionsDiv.appendChild(fixBtn);
        }

        // (v28.16) أزرار إضافية اختيارية عامة (مش مرتبطة بمنطق "تصليح" بتاع extraAction) - بتتحط
        // جوا هيدر النتيجة نفسها بدل ما نضيف زرار تايه في المنيو الرئيسي، مفيدة لأي panel محتاج فعل
        // إضافي خاص بيه بس (زي تصدير نسخة احتياطية للإحصائية الشاملة).
        if (Array.isArray(extraButtons)) {
            extraButtons.forEach(cfg => {
                const b = document.createElement('button');
                b.className = 'tx-panel-btn ' + (cfg.className || 'copy');
                b.textContent = cfg.label;
                b.onclick = () => cfg.onClick();
                actionsDiv.appendChild(b);
            });
        }

        const copyBtn = document.createElement('button');
        copyBtn.className = 'tx-panel-btn copy';
        copyBtn.textContent = '📋 نسخ';
        actionsDiv.appendChild(copyBtn);

        const closeBtn = document.createElement('button');
        closeBtn.className = 'tx-panel-btn close-icon';
        closeBtn.textContent = '✕';
        actionsDiv.appendChild(closeBtn);

        header.appendChild(titleDiv);
        header.appendChild(actionsDiv);

        const body = document.createElement('div');
        body.className = 'tx-panel-body';

        const rawLines = [];

        if (totalItems === 0) {
            body.innerHTML = '<div class="tx-panel-empty">✅ ' + escapeHtml(emptyMessage || 'تمام — مفيش أي مشاكل') + '</div>';
        } else {
            sections.forEach(sec => {
                if (sec.heading) {
                    const h = document.createElement('div');
                    h.className = 'tx-panel-heading';
                    h.textContent = sec.heading;
                    body.appendChild(h);
                    rawLines.push('━━━ ' + sec.heading + ' ━━━');
                }
                const headingSerial = extractSerialFromString(sec.heading);
                sec.items.forEach(item => {
                    const itemTextForSerial = typeof item === 'string' ? item : item.text;
                    const explicitSerial = (typeof item === 'object' && typeof item.serial === 'number') ? item.serial : null;
                    const serial = explicitSerial !== null ? explicitSerial : (extractSerialFromString(itemTextForSerial) ?? headingSerial);
                    body.appendChild(buildItemElement(item, rawLines, serial, () => overlay.remove()));
                });
            });
        }

        box.appendChild(header);
        box.appendChild(body);
        overlay.appendChild(box);
        document.body.appendChild(overlay);

        const rawText = rawLines.length > 0 ? rawLines.join('\n') : (emptyMessage || 'تمام — مفيش أي مشاكل');

        closeBtn.onclick = () => overlay.remove();
        copyBtn.onclick = () => {
            const ok = fallbackCopy(rawText);
            showToast(ok ? 'تم نسخ النتائج ✅' : 'فشل النسخ ❌', !ok);
        };
        if (fixBtn) {
            fixBtn.onclick = async () => {
                if (extraAction.confirmMessage) {
                    const ok = await showGlassConfirm(extraAction.confirmMessage);
                    if (!ok) return;
                }
                fixBtn.disabled = true;
                fixBtn.textContent = extraAction.loadingLabel || '⏳ جاري التصليح...';
                try {
                    const count = await runBatchOperation('fix', () => extraAction.onClick());
                    overlay.remove();
                    const msg = typeof extraAction.successMessage === 'function'
                        ? extraAction.successMessage(count)
                        : ('تم تصليح ' + (count || 0) + ' سيجمنت ✅ - جرب تعمل الفحص تاني للتأكيد');
                    showToast(msg);
                } catch (err) {
                    console.error('[AutoFix] خطأ:', err);
                    fixBtn.disabled = false;
                    fixBtn.textContent = extraAction.label || '🔧 تصليح تلقائي';
                    showToast('حصل خطأ أثناء التصليح ❌', true);
                }
            };
        }

        function escHandler(e) {
            if (e.key === 'Escape') {
                overlay.remove();
                document.removeEventListener('keydown', escHandler);
            }
        }
        document.addEventListener('keydown', escHandler);
    }

    // بيدور على السيجمنتات اللي رقمها في serialSet (عبر كل الصفحات/السكرول) وبيطبّق fixFn على النص بتاعها
    async function fixSegmentsBySerial(serialSet, fixFn) {
        const remaining = new Set(serialSet);
        let fixedCount = 0;

        function tryFixVisible() {
            const rows = document.querySelectorAll('#changyuliu_table > tr');
            rows.forEach(row => {
                const serialCell = row.querySelector('.number');
                const textarea = row.querySelector('.textContent .mark-content-textarea');
                if (!serialCell || !textarea) return;

                const serial = parseInt(serialCell.textContent.trim(), 10);
                if (!remaining.has(serial)) return;

                const raw = textarea.value !== undefined ? textarea.value : textarea.textContent;
                const fixed = fixFn(raw || '', serial);
                if (fixed !== raw) {
                    setNativeTextareaValue(textarea, fixed);
                    fixedCount++;
                }
                remaining.delete(serial);
            });
        }

        // نفحص المرئي حالياً الأول قبل أي تنقل - يغطي حالة عدم وجود نافيجيشن ولا سكرول (كل الصفوف ظاهرة أصلاً)
        tryFixVisible();

        const navButtons = findNavButtons();
        if (navButtons.length > 0) {
            for (const navBtn of navButtons) {
                if (remaining.size === 0) break;
                navBtn.click();
                await sleep(500);
                tryFixVisible();
            }
        } else if (remaining.size > 0) {
            const container = document.querySelector('#changyuliu_table')?.closest('[style*="overflow"]');
            if (container) {
                container.scrollTop = 0;
                await sleep(300);
                let stableCount = 0;
                let prevRemaining = remaining.size;

                while (stableCount < 2 && remaining.size > 0) {
                    tryFixVisible();
                    container.scrollTop += container.clientHeight * 0.6;
                    await sleep(400);

                    if (remaining.size === prevRemaining) stableCount++;
                    else stableCount = 0;
                    prevRemaining = remaining.size;
                }
            }
        }

        return fixedCount;
    }

    // ==================== لوحة "المراجعة الشاملة" — Segmented Tabs بأسلوب iOS (v10.0) ====================
    function ensureReviewStyles() {
        if (document.getElementById('tx-review-style')) return;
        const style = document.createElement('style');
        style.id = 'tx-review-style';
        style.textContent = `

            /* التابات نفسها (review + help) متعرّفة مرة واحدة في ensurePopupSystemStyles */
            .tx-review-tab-badge {
                background: rgba(var(--tx-danger), 0.85); color: #fff; border-radius: 999px;
                padding: 0 7px; font: 800 10.5px/16px var(--tx-font); margin-inline-start: 2px; font-variant-numeric: tabular-nums;
            }
            .tx-review-tab.active .tx-review-tab-badge { animation: tx-badge-pulse 1.8s infinite; }
        `;
        document.head.appendChild(style);
    }

    // tabs: [{ id, label, sections, emptyMessage, fixAction, excludeFromTotal }]
    // options.combinedFixAction (اختياري): لو موجودة، زرار "تصليح الكل" هيندهلها هي بس مرة واحدة بدل
    // ما يلف على كل تاب على حدة وينده fixAction بتاعه - كل fixAction فيهم بيعمل جولة تصفّح كاملة لوحده
    // (زي مسافات + تشكيل + قواعد كتابة)، فلو اتنادوا التلاتة كل واحد لوحده بيبقى 3 جولات تصفّح كاملة
    // بدل واحدة. استخدمها لما عندك أكتر من fixAction حقيقي في نفس اللوحة (زي "🚀 مراجعة شاملة").
    function showReviewPanel(tabs, options, extraButtons) {
        options = options || {};
        ensurePanelStyles();
        ensureReviewStyles();

        let activeTabId = tabs[0].id;
        const totalAll = tabs.reduce((sum, t) => sum + (t.excludeFromTotal ? 0 : t.sections.reduce((s2, sec) => s2 + sec.items.length, 0)), 0);

        const overlay = document.createElement('div');
        overlay.className = 'tx-panel-overlay';
        overlay.onclick = (e) => { if (e.target === overlay) overlay.remove(); };

        const box = document.createElement('div');
        box.className = 'tx-panel-box';
        box.style.width = '700px';

        const header = document.createElement('div');
        header.className = 'tx-panel-header';

        const titleDiv = document.createElement('div');
        titleDiv.className = 'tx-panel-title';
        titleDiv.innerHTML = '🚀 المراجعة الشاملة' + (totalAll > 0 ? ' <span class="tx-panel-badge pulse">' + totalAll + '</span>' : '');

        const actionsDiv = document.createElement('div');
        actionsDiv.className = 'tx-panel-actions';

        let fixAllBtn = null;
        if (totalAll > 0 && (tabs.some(t => typeof t.fixAction === 'function') || typeof options.combinedFixAction === 'function')) {
            fixAllBtn = document.createElement('button');
            fixAllBtn.className = 'tx-panel-btn fix';
            fixAllBtn.textContent = '🔧 تصليح الكل';
            actionsDiv.appendChild(fixAllBtn);
        }

        // (v28.16) أزرار إضافية اختيارية (زي تصدير التقرير) بتتحط جوا هيدر البانل نفسه بدل زرار
        // منفصل في المنيو الرئيسي - نفس فكرة extraButtons بتاعة showResultsPanel.
        if (Array.isArray(extraButtons)) {
            extraButtons.forEach(cfg => {
                const b = document.createElement('button');
                b.className = 'tx-panel-btn ' + (cfg.className || 'copy');
                b.textContent = cfg.label;
                b.onclick = () => cfg.onClick();
                actionsDiv.appendChild(b);
            });
        }

        const copyBtn = document.createElement('button');
        copyBtn.className = 'tx-panel-btn copy';
        copyBtn.textContent = '📋 نسخ الكل';
        actionsDiv.appendChild(copyBtn);

        const closeBtn = document.createElement('button');
        closeBtn.className = 'tx-panel-btn close-icon';
        closeBtn.textContent = '✕';
        actionsDiv.appendChild(closeBtn);

        header.appendChild(titleDiv);
        header.appendChild(actionsDiv);

        const tabBar = document.createElement('div');
        tabBar.className = 'tx-review-tabbar';
        const tabButtons = {};

        const body = document.createElement('div');
        body.className = 'tx-panel-body';

        function renderActiveTab() {
            Object.keys(tabButtons).forEach(id => tabButtons[id].classList.toggle('active', id === activeTabId));
            body.innerHTML = '';
            const tab = tabs.find(t => t.id === activeTabId);
            const count = tab.sections.reduce((s, sec) => s + sec.items.length, 0);

            if (count === 0) {
                body.innerHTML = '<div class="tx-panel-empty">✅ ' + escapeHtml(tab.emptyMessage || 'مفيش أي مشاكل') + '</div>';
                return;
            }

            tab.sections.forEach(sec => {
                if (sec.heading) {
                    const h = document.createElement('div');
                    h.className = 'tx-panel-heading';
                    h.textContent = sec.heading;
                    body.appendChild(h);
                }
                const headingSerial = extractSerialFromString(sec.heading);
                sec.items.forEach(item => {
                    const itemTextForSerial = typeof item === 'string' ? item : item.text;
                    const explicitSerial = (typeof item === 'object' && typeof item.serial === 'number') ? item.serial : null;
                    const serial = explicitSerial !== null ? explicitSerial : (extractSerialFromString(itemTextForSerial) ?? headingSerial);
                    body.appendChild(buildItemElement(item, null, serial, () => overlay.remove()));
                });
            });
        }

        tabs.forEach(tab => {
            const count = tab.sections.reduce((s, sec) => s + sec.items.length, 0);
            const tb = document.createElement('button');
            tb.className = 'tx-review-tab' + (tab.id === activeTabId ? ' active' : '');
            tb.innerHTML = tab.label + (count > 0 && !tab.excludeFromTotal ? ' <span class="tx-review-tab-badge">' + count + '</span>' : '');
            tb.onclick = () => { activeTabId = tab.id; renderActiveTab(); };
            tabBar.appendChild(tb);
            tabButtons[tab.id] = tb;
        });

        renderActiveTab();

        box.appendChild(header);
        box.appendChild(tabBar);
        box.appendChild(body);
        overlay.appendChild(box);
        document.body.appendChild(overlay);

        closeBtn.onclick = () => overlay.remove();
        copyBtn.onclick = () => {
            const lines = [];
            tabs.forEach(tab => {
                lines.push('==== ' + tab.label + ' ====');
                if (tab.sections.length === 0) {
                    lines.push(tab.emptyMessage || 'مفيش أي مشاكل');
                } else {
                    tab.sections.forEach(sec => {
                        if (sec.heading) lines.push('━━━ ' + sec.heading + ' ━━━');
                        sec.items.forEach(item => lines.push(typeof item === 'string' ? item : item.text));
                    });
                }
                lines.push('');
            });
            const ok = fallbackCopy(lines.join('\n'));
            showToast(ok ? 'تم نسخ كل النتائج ✅' : 'فشل النسخ ❌', !ok);
        };

        if (fixAllBtn) {
            fixAllBtn.onclick = async () => {
                fixAllBtn.disabled = true;
                fixAllBtn.textContent = '⏳ جاري تصليح كل حاجة...';
                let totalFixed = 0;
                await runBatchOperation('fix-all', async () => {
                    if (typeof options.combinedFixAction === 'function') {
                        // جولة تصفّح واحدة بس بتطبّق كل الفيكسات مع بعض (بدل جولة منفصلة لكل تاب)
                        try {
                            totalFixed += (await options.combinedFixAction()) || 0;
                        } catch (err) {
                            console.error('[Review Fix] خطأ في التصليح المجمّع:', err);
                        }
                    } else {
                        for (const tab of tabs) {
                            if (typeof tab.fixAction === 'function') {
                                try {
                                    totalFixed += (await tab.fixAction()) || 0;
                                } catch (err) {
                                    console.error('[Review Fix] خطأ في ' + tab.id + ':', err);
                                }
                            }
                        }
                    }
                });
                overlay.remove();
                showToast('تم تصليح ' + totalFixed + ' سيجمنت في المراجعة الشاملة ✅ - يفضل تعمل الفحص تاني للتأكيد');
            };
        }

        function escHandler(e) {
            if (e.key === 'Escape') {
                overlay.remove();
                document.removeEventListener('keydown', escHandler);
            }
        }
        document.addEventListener('keydown', escHandler);
    }

    // ==================== دوال تصفية التكرار (منع ظهور نفس السيجمنت/الخطأ مرتين) (v13.0) ====================
    // بيحصل لما نفس السيجمنت يتقرا أكتر من مرة عبر صفحات النافيجيشن/السكرول المتداخلة
    function dedupeBySerial(arr) {
        const seen = new Set();
        return arr.filter(item => {
            const serial = typeof item === 'object' ? item.serial : item;
            if (seen.has(serial)) return false;
            seen.add(serial);
            return true;
        });
    }

    // بيدمج كل نتائج "قواعد الكتابة" لنفس السيجمنت في عنصر واحد، وبيشيل تكرار نفس رسالة الخطأ جوه نفس السيجمنت
    function dedupeWritingResults(results) {
        const map = new Map();
        results.forEach(r => {
            if (!map.has(r.serial)) map.set(r.serial, new Set());
            r.issues.forEach(i => map.get(r.serial).add(i));
        });
        return Array.from(map.keys()).sort((a, b) => a - b).map(serial => ({ serial, issues: Array.from(map.get(serial)) }));
    }

    // بيلم أرقام السيجمنتات اللي فيها مشاكل + نص كل مشكلة، من نتيجة تابات "المراجعة الشاملة"
    // بيتستخدم في التنقل بالكيبورد (Alt+↓/↑) وفي عرض تلميح "شو المشكلة" في زرار التنقل العائم
    function computeProblemDataFromTabs(tabs) {
        const serialsSet = new Set();
        const messages = new Map();
        tabs.forEach(tab => {
            if (tab.excludeFromTotal) return;
            tab.sections.forEach(sec => {
                const headingSerial = extractSerialFromString(sec.heading);
                sec.items.forEach(item => {
                    const itemText = typeof item === 'string' ? item : item.text;
                    const explicitSerial = (typeof item === 'object' && typeof item.serial === 'number') ? item.serial : null;
                    const serial = explicitSerial !== null ? explicitSerial : (extractSerialFromString(itemText) ?? headingSerial);
                    if (typeof serial === 'number' && !isNaN(serial)) {
                        serialsSet.add(serial);
                        if (!messages.has(serial)) messages.set(serial, []);
                        // بنشيل رقم السيجمنت من أول الرسالة لو موجود عشان التلميح يبقى نضيف.
                        // لو النص كله كان "سيجمنت N" بس من غير أي تفاصيل زيادة، بناخد الوصف من عنوان
                        // المجموعة (sec.heading) اللي فيه شرح المشكلة الحقيقي - عشان التلميح ميبقاش فاضي
                        // ويكرر رقم السيجمنت بس (المشكلة اللي ظهرت في الصورة).
                        const cleaned = String(itemText).replace(/^سيجمنت\s+\d+\s*[-—:]?\s*/, '').trim();
                        const finalMsg = cleaned || sec.heading || itemText;
                        if (!messages.get(serial).includes(finalMsg)) messages.get(serial).push(finalMsg);
                    }
                });
            });
        });
        return { serials: Array.from(serialsSet).sort((a, b) => a - b), messages };
    }

    // بيشغّل كل الفحوصات مع بعض ويعرضهم في لوحة واحدة بتابات
    // بيلمّ من كل صف ظاهر كل المعلومات اللي محتاجها الفحوصات الأربعة مرة واحدة بس (مسافات، إنجليزي/تشكيل،
    // قواعد الكتابة، معلومات التاج) - بدل ما كل فحص يعمل querySelectorAll ويقرا الصف لوحده على حدة.
    // ملحوظة: بنستخدم raw من غير trim لفحص المسافات (محتاج يعرف لو في مسافة أول/آخر السيجمنت)،
    // وtrimmed (raw.trim()) للفحوصات التانية زي الأصل بالظبط.
    // بتحوّل نص السيجمنت لمصفوفة كلمات (بتشيل علامات الترقيم عشان "شبكة،" و"شبكة." يتطابقوا ككلمة واحدة)
    function tokenizeWords(text) {
        if (!text) return [];
        return text.replace(/[،.؟]/g, ' ').replace(/\s+/g, ' ').trim().split(' ').filter(Boolean);
    }

    // بيدوّر على أطول تتابع كلمات متجاور متطابق بين سيجمنتين - ده بيلقط "جملة كاملة اتكررت" حتى لو
    // كانت جوه سيجمنت مدموجة مع كلام تاني (زي مثال: جملة كانت جزء من جملة أطول في سيجمنت، وبعدين
    // اتكررت لوحدها في سيجمنت تاني - مش بالضرورة نفس حدود الجملة بالترقيم في المكانين). DP بسيط
    // O(عدد كلمات×عدد كلمات) - سريع جداً لأن كل سيجمنت عادة أقل من 40-50 كلمة.
    function longestCommonWordRun(wordsA, wordsB) {
        if (wordsA.length === 0 || wordsB.length === 0) return { length: 0, text: '' };
        let best = 0, bestEndA = 0;
        let prevRow = new Array(wordsB.length + 1).fill(0);
        for (let i = 1; i <= wordsA.length; i++) {
            const curRow = new Array(wordsB.length + 1).fill(0);
            for (let j = 1; j <= wordsB.length; j++) {
                if (wordsA[i - 1] === wordsB[j - 1]) {
                    curRow[j] = prevRow[j - 1] + 1;
                    if (curRow[j] > best) { best = curRow[j]; bestEndA = i; }
                }
            }
            prevRow = curRow;
        }
        return { length: best, text: wordsA.slice(bestEndA - best, bestEndA).join(' ') };
    }

    // (v29.26.7) حد أقصى لمدة سيجمنت الكلام الواحد = 13 ثانية (التاجات مستثناة - شوف v29.26.11). أي سيجمنت كلام أطول منها بيتعتبر ايرور في F2.
    // المدة بتتقرا من الـregion بتاع الموجة (data-time.all) زي باقي الفحوصات، ولو الـregion مش لاقيه
    // بنرجع لبيانات Vue بتاعة الموقع (end - start). لو معرفناش نجيب مدة خالص بنتجاهل السيجمنت (مش بنعمله ايرور بالغلط).
    const MAX_SEGMENT_SECONDS = 13;
    function getSegmentDurationSec(regionId, serial) {
        let d = getRegionDuration(regionId);
        if (d !== null) return d;
        try {
            const vm = findMarkVueInstance();
            const data = vm && vm.speechInfo && vm.speechInfo.data;
            if (data && data.length) {
                const item = data.find(x => String(x.index) === String(regionId)) || data[serial - 1];
                if (item) {
                    const len = parseFloat(item.end) - parseFloat(item.start);
                    if (!isNaN(len)) return len;
                }
            }
        } catch (e) { /* تجاهل */ }
        return null;
    }

    // ==================== (v29.26.18) قراءة لحظية لكل السيجمنتات من بيانات الموقع ====================
    // بدل ما F2 وF4 وF8 وT يلفّوا على صفحات Navigation واحدة واحدة (نص ثانية انتظار لكل صفحة)، بنقرا كل
    // السيجمنتات مرة واحدة من vm.speechInfo.data بتاع الموقع: content = النص، sign.role = التاجات (Attribute)،
    // index = رقم الـregion، start/end = الحدود. الأمان: قبل ما نعتمد على البيانات دي بنقارنها بالصفوف الظاهرة
    // فعلاً (الترقيم والنص بالحرف والتاجات) وبنتأكد إنها بتغطي كل صفحات Navigation. لو أي حاجة متطابقتش
    // بنرجّع null والكود القديم (التنقل بين الصفحات) بيشتغل زي ما كان بالظبط - فمفيش نتيجة غلط بصمت.
    let txFastFailReason = '';
    // الاسكريبت بيحتفظ بنسخة Vue واحدة (markVueInstance). في مركز التاسكات (تاسكات كتير ورا بعض) النسخة دي ممكن
    // تبقى بتاعة تاسك قديم: لو القراءة الأولى فشلت بنصفّر النسخة المخزّنة ونجرّب تاني مرة واحدة قبل ما نرجع للطريقة القديمة.
    function txVueFastSnapshot() {
        if (markVueInstance && markVueInstance._isDestroyed) markVueInstance = null;
        const first = txVueFastSnapshotOnce(true);
        if (first) return first;
        markVueInstance = null;
        return txVueFastSnapshotOnce(false);
    }
    function txVueFastSnapshotOnce(quiet) {
        txFastFailReason = '';
        const fail = (why) => { txFastFailReason = why; if (!quiet) try { console.info('[أدوات التفريغ] القراءة اللحظية اتعطّلت (' + why + ') - رجعنا للتنقل بين الصفحات'); } catch (e) { /* تجاهل */ } return null; };
        try {
            const vm = findMarkVueInstance();
            const data = vm && vm.speechInfo && vm.speechInfo.data;
            if (!data || !data.length) return fail('مفيش بيانات');
            const items = [];
            for (let i = 0; i < data.length; i++) {
                const d = data[i];
                if (!d) return fail('عنصر فاضي');
                const role = (d.sign && Array.isArray(d.sign.role)) ? d.sign.role.map(x => String(x).trim()) : [];
                items.push({ serial: i + 1, index: Number(d.index), regionId: '', start: Number(d.start), end: Number(d.end), raw: d.content == null ? '' : String(d.content), tags: role });
            }
            let checked = 0, offset = null;
            const rows = document.querySelectorAll('#changyuliu_table > tr');
            for (const row of rows) {
                const snap = collectRowSnapshot(row);
                if (!snap) continue;
                const it = items[snap.serial - 1];
                if (!it) return fail('سيريال برا البيانات');
                const off = Number(snap.regionId) - it.index;
                if (isNaN(off)) return fail('رقم الصف مش رقم');
                if (offset === null) offset = off; else if (off !== offset) return fail('ترقيم الصفوف مش متسق');
                if (it.raw !== snap.raw) return fail('نص مختلف في السيجمنت ' + snap.serial);
                if (it.tags.join('|') !== snap.attrTagTexts.join('|')) return fail('تاجات مختلفة في السيجمنت ' + snap.serial);
                checked++;
            }
            if (checked === 0 || offset === null) return fail('مفيش صفوف ظاهرة للمقارنة');
            items.forEach(it => { it.regionId = String(it.index + offset); });
            let maxEnd = 0;
            findNavButtons().forEach(b => {
                const m = (b.textContent || '').match(/(\d+)\s*[-\u2013\u2014~]\s*(\d+)/);
                if (m) maxEnd = Math.max(maxEnd, parseInt(m[2], 10));
            });
            if (maxEnd && items.length < maxEnd) return fail('البيانات أقل من صفحات Navigation');
            return items;
        } catch (e) { return fail('خطأ: ' + (e && e.message ? e.message : e)); }
    }

    // نفس قاعدة extractVisibleRows بالظبط (مسافات متقلصة + استبعاد النص الفاضي وشكل التاج) - للنسخ (F8)
    function txLinesFromSnapshot(items) {
        const lines = [];
        items.forEach(it => {
            const text = it.raw.replace(/\s+/g, ' ').trim();
            if (/^<[A-Za-z]+>$/.test(text)) return;
            if (text) lines.push(text);
        });
        return lines;
    }

    function scanVisiblePageForFullReview(acc) {
        const rows = document.querySelectorAll('#changyuliu_table > tr');

        rows.forEach(row => {
            const snap = collectRowSnapshot(row);
            if (!snap) return;
            scanSnapshotForFullReview(snap, acc, row);
        });
    }

    // (v29.26.18) جسم الفحص اتفصل عن قراءة الـDOM عشان يشتغل على صف حقيقي (row) أو على بيانات لحظية (row = null)
    function scanSnapshotForFullReview(snap, acc, row) {
        {
            const { serial, raw, trimmed, hasAttrTag, attrTagTexts, regionId } = snap;

            let hasErrorLevel = false; // مسافات = 'error' زي الأصل بالظبط
            let hasWarnLevel = false;  // إنجليزي/تشكيل/قواعد كتابة = 'warn' زي الأصل بالظبط

            let hasRedLevel = false; // (v29.32.4) خطأ فعلي بيلوّن الصف أحمر
            if (raw && /^\s|\s$/.test(raw)) { acc.allLeadTrail.add(serial); hasErrorLevel = true; wsDetailMap.lead.set(serial, describeWhitespaceIssues(raw).lead); }
            if (raw && acc.doubleSpaceRegex.test(raw)) { acc.allDoubleSpace.add(serial); hasErrorLevel = true; wsDetailMap.dbl.set(serial, describeWhitespaceIssues(raw).dbl); }

            if (trimmed) {
                const englishWords = countPureEnglishWords(trimmed);
                if (englishWords.length >= 3) {
                    acc.allEnglishIssues.push({ serial, count: englishWords.length, words: englishWords.join(', ') });
                    hasWarnLevel = true;
                }
                if (acc.tashkeelRegex.test(trimmed)) { acc.allTashkeelIssues.add(serial); hasWarnLevel = true; }
            }

            const writingIssues = checkWritingRules(trimmed, hasAttrTag);
            if (writingIssues.length > 0) {
                acc.allWritingResults.push({ serial, issues: writingIssues });
                hasWarnLevel = true;
                if (writingIssues.some(i => txMsgSeverity(i) === 'error')) hasRedLevel = true;
            }

            // (v29.26.11) السيجمنت اللي فيه كلام مينفعش يتعدى 13 ثانية - ايرور. التاجات (NOISE/DEAF/OOV/OVERLAP...)
            // مش داخلة في الحد ده خالص، ليها قواعدها لوحدها (زي NOISE مينفعش يقل عن نص ثانية). "فيه كلام" = فيه نص
            // فعلي بعد ما نشيل أي <تاج> منه.
            const hasRealSpeech = !!trimmed && /\S/.test(trimmed.replace(/<[^<>]*>/g, ''));
            const segDur = hasRealSpeech ? getSegmentDurationSec(regionId, serial) : null;
            if (segDur !== null && segDur > MAX_SEGMENT_SECONDS) {
                acc.allLongSegments.push({ serial, duration: segDur });
                hasErrorLevel = true;
                hasRedLevel = true;
            }

            acc.tagInfo[serial] = { serial, text: trimmed, hasAttrTag, attrTagTexts, regionId };

            if (row) setRowStatus(row, hasRedLevel ? 'error' : ((hasErrorLevel || hasWarnLevel) ? 'warn' : null));
        }
    }

    async function runFullReview(btn) {
        await pickDialect();

        txBtnBusy(btn, 'جاري المراجعة الشاملة...');
        btn.disabled = true;

        // كانت الأداة بتعمل 4 جولات تصفّح كاملة منفصلة (مسافات، إنجليزي/تشكيل، قواعد كتابة، تاجات) -
        // كل جولة بتدوس على كل أزرار الصفحات وتستنى 500ms في كل صفحة. دلوقتي جولة واحدة بس بتجمع
        // كل حاجة سوا، فبدل 4×عدد الصفحات كليك بقت مرة واحدة بس × عدد الصفحات.
        const acc = {
            allLeadTrail: new Set(),
            allDoubleSpace: new Set(),
            allEnglishIssues: [],
            allTashkeelIssues: new Set(),
            allWritingResults: [],
            allLongSegments: [],
            tagInfo: {},
            doubleSpaceRegex: /[^\s،؛:؟!.]\s{2,}[^\s،؛:؟!.]/,
            tashkeelRegex: TASHKEEL_TEST_RE
        };

        // (v29.26.18) الأول القراءة اللحظية من بيانات الموقع (من غير تنقل بين الصفحات). لو فشلت (txVueFastSnapshot
        // رجّعت null) بنكمّل بالطريقة القديمة بالظبط.
        const fastItems = txVueFastSnapshot();
        if (fastItems) {
            const rowBySerial = new Map();
            document.querySelectorAll('#changyuliu_table > tr').forEach(r => { const n = getSerialFromRow(r); if (n !== null) rowBySerial.set(n, r); });
            fastItems.forEach(it => {
                scanSnapshotForFullReview(
                    { serial: it.serial, raw: it.raw, trimmed: it.raw.trim(), hasAttrTag: it.tags.length > 0, attrTagTexts: it.tags, regionId: it.regionId },
                    acc, rowBySerial.get(it.serial) || null
                );
            });
        } else {
            const navButtons = findNavButtons();
            scanVisiblePageForFullReview(acc); // الصفحة الظاهرة حالياً كمان
            if (navButtons.length > 0) {
                for (const navBtn of navButtons) {
                    navBtn.click();
                    await sleep(500);
                    scanVisiblePageForFullReview(acc);
                }
            }
        }

        const allLeadTrail = acc.allLeadTrail;
        const allDoubleSpace = acc.allDoubleSpace;
        const allTashkeelIssues = acc.allTashkeelIssues;
        let allEnglishIssues = dedupeBySerial(acc.allEnglishIssues);
        let allWritingResults = dedupeWritingResults(acc.allWritingResults);

        const tagInfo = acc.tagInfo;
        const sortedSerials = Object.keys(tagInfo).map(Number).sort((a, b) => a - b);
        const adjacentDuplicates = [];
        const missingAttrTags = [];
        const shortDurationTags = [];
        const multipleTagsPerSegment = [];
        const taggedWithText = [];

        let totalTagSeconds = 0, tagCount = 0;
        const perTagTotals = {};
        let totalSpeechSeconds = 0, speechCount = 0;

        // كان بيعمل document.querySelector منفصلة لكل سيجمنت متاج/بيه كلام (ممكن يبقوا مئات) - دلوقتي
        // بحث واحد على كل الـregions الظاهرة وMap بيتقرا منها بدل البحث المتكرر (شوف buildRegionDurationCache)
        const regionDurationCache = buildRegionDurationCache();

        for (let i = 0; i < sortedSerials.length; i++) {
            const cur = tagInfo[sortedSerials[i]];
            const isTagShaped = /^<[A-Za-z]+>$/.test(cur.text);

            if (isTagShaped && !cur.hasAttrTag) missingAttrTags.push(cur.serial);
            if (cur.hasAttrTag && cur.attrTagTexts.length > 1) multipleTagsPerSegment.push({ serial: cur.serial, tags: cur.attrTagTexts.join(', ') });
            if (cur.hasAttrTag && cur.attrTagTexts.includes('<NOISE>')) {
                const duration = getRegionDuration(cur.regionId, regionDurationCache);
                if (duration !== null && duration < 0.5) shortDurationTags.push({ serial: cur.serial, duration });
            }
            if (cur.hasAttrTag && cur.text && !isTagShaped) taggedWithText.push({ serial: cur.serial, text: cur.text });

            if (i < sortedSerials.length - 1) {
                const next = tagInfo[sortedSerials[i + 1]];
                const nextIsTagShaped = /^<[A-Za-z]+>$/.test(next.text);
                if (isTagShaped && nextIsTagShaped && cur.text === next.text && cur.hasAttrTag && next.hasAttrTag) {
                    adjacentDuplicates.push([cur.serial, next.serial, cur.text]);
                }
            }

            if (isTagShaped && cur.hasAttrTag) {
                const duration = getRegionDuration(cur.regionId, regionDurationCache);
                if (duration !== null) {
                    totalTagSeconds += duration;
                    tagCount++;
                    perTagTotals[cur.text] = (perTagTotals[cur.text] || 0) + duration;
                }
            }

            if (!isTagShaped && !cur.hasAttrTag && cur.text) {
                const duration = getRegionDuration(cur.regionId, regionDurationCache);
                if (duration !== null) {
                    totalSpeechSeconds += duration;
                    speechCount++;
                }
            }
        }

        // (v28.16) بنقارن كل زوج سيجمنتات فيهم كلام حقيقي (مش تاج فاضي) مع بعض، ونلقط أطول تتابع كلمات
        // متطابق بينهم. عتبة 4 كلمات فأكتر عشان مانطلّعش تنبيه على كلمة واحدة متكررة (زي اسم شخص أو
        // فيلر ووردز) - المطلوب جملة/جزء جملة كامل فعلاً زي ما اتطلب بالظبط.
        const speechEntriesForDupes = sortedSerials
            .map(s => tagInfo[s])
            .filter(cur => cur.text && !/^<[A-Za-z]+>$/.test(cur.text))
            .map(cur => ({ serial: cur.serial, words: tokenizeWords(cur.text) }))
            .filter(entry => entry.words.length > 0);

        const duplicateSentenceGroups = [];
        for (let i = 0; i < speechEntriesForDupes.length; i++) {
            for (let j = i + 1; j < speechEntriesForDupes.length; j++) {
                const run = longestCommonWordRun(speechEntriesForDupes[i].words, speechEntriesForDupes[j].words);
                if (run.length >= 4) {
                    duplicateSentenceGroups.push({ serials: [speechEntriesForDupes[i].serial, speechEntriesForDupes[j].serial], sentence: run.text });
                }
            }
        }
        duplicateSentenceGroups.sort((a, b) => a.serials[0] - b.serials[0]);

        txBtnReset(btn);
        btn.disabled = false;

        cacheQATagProblems(missingAttrTags, shortDurationTags);

        const overviewSections = [
            {
                heading: null,
                items: [
                    { text: '🗣️ زمن الكلام الفعلي: ' + formatSecondsToHMS(totalSpeechSeconds) + ' — ' + speechCount + ' سيجمنت', type: 'ok' },
                    { text: '⏱️ زمن التاجات: ' + formatSecondsToHMS(totalTagSeconds) + ' — ' + tagCount + ' سيجمنت', type: 'ok' }
                ]
            }
        ];
        if (Object.keys(perTagTotals).length > 0) {
            overviewSections.push({
                heading: 'تفصيل زمن التاجات حسب النوع',
                items: Object.keys(perTagTotals).map(tag => ({ text: tag + ': ' + perTagTotals[tag].toFixed(1) + ' ثانية', type: 'info' }))
            });
        }

        const whitespaceSections = [];
        if (allLeadTrail.size > 0) whitespaceSections.push({ heading: '📏 مسافة زيادة في أول/آخر السيجمنت', items: Array.from(allLeadTrail).sort((a, b) => a - b).map(s => ({ text: wsSerialItemText(s, 'lead'), type: 'warn' })) });
        if (allDoubleSpace.size > 0) whitespaceSections.push({ heading: '📏 مسافة مزدوجة بين كلمتين جوه السيجمنت', items: Array.from(allDoubleSpace).sort((a, b) => a - b).map(s => ({ text: wsSerialItemText(s, 'dbl'), type: 'warn' })) });

        const engTashSections = [];
        if (allEnglishIssues.length > 0) engTashSections.push({ heading: '🔤 سيجمنتات فيها 3 كلمات إنجليزي أو أكتر', items: allEnglishIssues.map(item => ({ text: 'سيجمنت ' + item.serial + ' — ' + item.count + ' كلمة: ' + item.words, type: 'warn' })) });
        if (allTashkeelIssues.size > 0) engTashSections.push({ heading: '🚫 سيجمنتات فيها تشكيل عربي', items: Array.from(allTashkeelIssues).sort((a, b) => a - b).map(s => ({ text: 'سيجمنت ' + s, type: 'warn' })) });

        const writingSections = allWritingResults.map(r => ({ heading: 'سيجمنت ' + r.serial, items: r.issues }));

        const tagSections = [];
        if (adjacentDuplicates.length > 0) tagSections.push({ heading: '🔗 تاجات متتالية من نفس النوع (مرشحة للدمج)', items: adjacentDuplicates.map(([a, b, tag]) => ({ text: 'سيجمنت ' + a + ' و ' + b + ' (' + tag + ')', type: 'warn' })) });
        if (missingAttrTags.length > 0) tagSections.push({ heading: '❌ سيجمنتات فيها نص تاج بدون Attribute', items: missingAttrTags.map(s => ({ text: 'سيجمنت ' + s, type: 'warn' })) });
        if (shortDurationTags.length > 0) tagSections.push({ heading: '⏱️ تاجات NOISE أقل من نص ثانية', items: shortDurationTags.map(item => ({ text: 'سيجمنت ' + item.serial + ' (' + item.duration.toFixed(3) + 's)', type: 'warn' })) });
        if (multipleTagsPerSegment.length > 0) tagSections.push({ heading: '🔢 سيجمنتات فيها أكتر من تاج واحد', items: multipleTagsPerSegment.map(item => ({ text: 'سيجمنت ' + item.serial + ' (' + item.tags + ')', type: 'warn' })) });
        if (taggedWithText.length > 0) tagSections.push({ heading: '📝 سيجمنتات فيها تاج + جملة كلام مع بعض', items: taggedWithText.map(item => ({ text: 'سيجمنت ' + item.serial, type: 'warn' })) });

        // (v29.26.7) سيجمنتات مدتها أكتر من 13 ثانية (ايرور) - dedupe بالسيريال لأن نفس الصف ممكن يتقرا مرتين بين الصفحات
        const longSegMap = new Map();
        acc.allLongSegments.forEach(it => longSegMap.set(it.serial, it));
        const longSegments = Array.from(longSegMap.values()).sort((a, b) => a.serial - b.serial);
        const durationSections = [];
        if (longSegments.length > 0) {
            durationSections.push({
                heading: '⏱️ سيجمنتات الكلام اللي مدتها أكتر من ' + MAX_SEGMENT_SECONDS + ' ثانية (ايرور - لازم تتقسم)',
                items: longSegments.map(it => ({ text: 'سيجمنت ' + it.serial + ' — ⏱️ ' + it.duration.toFixed(2) + ' ثانية (زيادة ' + (it.duration - MAX_SEGMENT_SECONDS).toFixed(2) + ' ث)', type: 'warn', serial: it.serial }))
            });
        }

        const duplicateSentenceSections = [];
        if (duplicateSentenceGroups.length > 0) {
            duplicateSentenceSections.push({
                heading: '🔁 جملة كاملة اتكررت حرفياً في أكتر من سيجمنت (يمكن نسيت تمسحها بعد نسخ/لصق)',
                items: duplicateSentenceGroups.map(g => ({ text: 'سيجمنت ' + g.serials.join(' و ') + ' — "' + g.sentence + '"', type: 'warn' }))
            });
        }

        // كان زرار "تصليح الكل" بينده على 3 fixAction منفصلة (مسافات، تشكيل، قواعد كتابة)، وكل واحدة فيهم
        // بتعمل جولة تصفّح كاملة لوحدها (fixSegmentsBySerial) - يعني 3 جولات صفحات كاملة لتصليح واحد.
        // هنا بنجمعهم في fixAction واحد بيعمل جولة تصفّح واحدة بس، وكل سيجمنت بياخد بس الفيكسات المناسبة له.
        const whitespaceFixSerials = new Set([...allLeadTrail, ...allDoubleSpace]);
        const tashkeelFixSerials = allTashkeelIssues;
        const writingFixSerials = new Set(allWritingResults.map(r => r.serial));
        const combinedFixAction = (whitespaceFixSerials.size > 0 || tashkeelFixSerials.size > 0 || writingFixSerials.size > 0)
            ? async () => {
                const combinedSerials = new Set([...whitespaceFixSerials, ...tashkeelFixSerials, ...writingFixSerials]);
                return await fixSegmentsBySerial(combinedSerials, (raw, serial) => {
                    let fixed = raw;
                    if (whitespaceFixSerials.has(serial)) fixed = fixed.trim().replace(/\s{2,}/g, ' ');
                    if (tashkeelFixSerials.has(serial)) fixed = stripTashkeel(fixed);
                    if (writingFixSerials.has(serial)) fixed = autoFixWritingIssues(fixed);
                    return fixed;
                });
            }
            : null;

        const tabs = [
            { id: 'overview', label: '📊 نظرة عامة', sections: overviewSections, emptyMessage: 'لا يوجد بيانات', excludeFromTotal: true, fixAction: null },
            {
                id: 'whitespace', label: '🔍 المسافات', sections: whitespaceSections, emptyMessage: 'مفيش أي مشاكل مسافات',
                fixAction: whitespaceSections.length > 0 ? async () => {
                    const serials = new Set([...allLeadTrail, ...allDoubleSpace]);
                    return await fixSegmentsBySerial(serials, (raw) => raw.trim().replace(/\s{2,}/g, ' '));
                } : null
            },
            {
                id: 'engtash', label: '🈯 إنجليزي/تشكيل', sections: engTashSections, emptyMessage: 'مفيش سيجمنتات فيها 3 كلمات إنجليزي أو أي تشكيل عربي',
                fixAction: allTashkeelIssues.size > 0 ? async () => {
                    return await fixSegmentsBySerial(allTashkeelIssues, (raw) => stripTashkeel(raw));
                } : null
            },
            {
                id: 'writing', label: '📐 قواعد الكتابة', sections: writingSections, emptyMessage: 'مفيش أي مخالفات',
                fixAction: writingSections.length > 0 ? async () => {
                    const serials = new Set(allWritingResults.map(r => r.serial));
                    return await fixSegmentsBySerial(serials, autoFixWritingIssues);
                } : null
            },
            {
                id: 'tags', label: '⚠️ التاجات', sections: tagSections, emptyMessage: 'مفيش أي مشاكل في التاجات',
                fixAction: null
            },
            {
                id: 'duration', label: '⏱️ المدة (+13ث)', sections: durationSections, emptyMessage: 'مفيش أي سيجمنت كلام مدته أكتر من ' + MAX_SEGMENT_SECONDS + ' ثانية',
                fixAction: null
            },
            {
                id: 'dupes', label: '🔁 جمل متكررة', sections: duplicateSentenceSections, emptyMessage: 'مفيش جمل كاملة متكررة حرفياً بين سيجمنتات مختلفة',
                fixAction: null
            }
        ];

        setReviewProblemData(computeProblemDataFromTabs(tabs));
        cacheReviewTabs(tabs);
        showReviewPanel(tabs, { combinedFixAction },
            [{ label: '🧾 تصدير المراجعة', className: 'copy', onClick: () => exportQualityReport() }]);

        // تذكير دايم: أي "فحص شامل" معناه إنك بتقرب تسلّم، فلازم متنساش تسجّل التاسك في الإحصائية
        setTimeout(() => showToast('متنساش: لما تخلّص التصليح وتقرب تسلّم، دوس ✅ إنهاء التاسك أو F4 عشان يتسجل في إحصائية اليوم 📊', false, 7000), 600);
    }

    let fullReviewBtnRef = null;
    function addFullReviewButton() {
        const btn = document.createElement('button');
        txInitToolBtn(btn, 'review', 'shield', 'مراجعة شاملة', 'review');

        btn.onclick = () => runFullReview(btn);
        document.body.appendChild(btn);
        fullReviewBtnRef = btn;
    }

    // ==================== الجزء 1: نسخ كل السيجمنتات ====================
    function extractVisibleRows() {
        const rows = document.querySelectorAll('#changyuliu_table > tr');
        const map = {};

        rows.forEach(row => {
            const serialCell = row.querySelector('.number');
            const contentCell = row.querySelector('.textContent .mark-content-textarea');
            if (!serialCell) return;

            const serial = parseInt(serialCell.textContent.trim(), 10);
            if (isNaN(serial)) return;

            let text = contentCell ? (contentCell.value || contentCell.textContent || '') : '';
            text = text.replace(/\s+/g, ' ').trim();

            if (/^<[A-Za-z]+>$/.test(text)) return;

            if (text) map[serial] = text;
        });

        return map;
    }

    // (v28.21.9) الأول بندوّر على أزرار الصفحات الحقيقية بتاعة الموقع (button.seg-tag جوه .seg-page - السلكتور
    // ده من الـHTML الحقيقي، شوف تعليق v28.12.4)، لأن الاعتماد على نص الزرار "رقم-رقم" لوحده كان بيفشل بصمت
    // لو الموقع كتب الرنج بشكل تاني (شرطة طويلة أو ~ أو غيره) - وساعتها كل العمليات اللي بتلف على كل الصفحات
    // (تفريغ الكل، النسخ، المراجعة...) كانت بتقع على السكرول وتغطي الصفحة الحالية بس. النص القديم فضل fallback.
    function findNavButtons() {
        const pageBtns = Array.from(document.querySelectorAll('.seg-page .seg-tag'))
            .filter(el => /\d/.test(el.textContent || ''));
        if (pageBtns.length > 0) return pageBtns;
        const all = Array.from(document.querySelectorAll('div, span, button, a'));
        return all.filter(el => {
            const txt = el.textContent.trim();
            return /^\d+\s*[-\u2013\u2014~]\s*\d+$/.test(txt) && el.children.length === 0;
        });
    }

    async function collectAllSegments() {
        // (v29.26.18) قراءة لحظية من بيانات الموقع لو اتطابقت مع الصفحة الظاهرة، وإلا الطريقة القديمة
        const fastItems = txVueFastSnapshot();
        if (fastItems) {
            const fastLines = txLinesFromSnapshot(fastItems);
            return { text: fastLines.join('\n'), count: fastLines.length, usedNav: false, usedFast: true };
        }
        const navButtons = findNavButtons();
        let allData = {};

        if (navButtons.length > 0) {
            for (const btn of navButtons) {
                btn.click();
                await sleep(500);
                Object.assign(allData, extractVisibleRows());
            }
        } else {
            const container = document.querySelector('#changyuliu_table')?.closest('[style*="overflow"]');
            if (container) {
                container.scrollTop = 0;
                await sleep(300);
                let stableCount = 0;
                let prevKeyCount = 0;

                while (stableCount < 2) {
                    Object.assign(allData, extractVisibleRows());
                    container.scrollTop += container.clientHeight * 0.6;
                    await sleep(400);

                    const currentKeyCount = Object.keys(allData).length;
                    if (currentKeyCount === prevKeyCount) stableCount++;
                    else stableCount = 0;
                    prevKeyCount = currentKeyCount;
                }
            }
        }

        const sortedKeys = Object.keys(allData).map(Number).sort((a, b) => a - b);
        const lines = sortedKeys.map(k => allData[k]).filter(t => t.length > 0);

        return { text: lines.join('\n'), count: lines.length, usedNav: navButtons.length > 0 };
    }

    function fallbackCopy(text) {
        const ta = document.createElement('textarea');
        ta.value = text;
        ta.style.position = 'fixed';
        ta.style.left = '-9999px';
        document.body.appendChild(ta);
        ta.focus();
        ta.select();
        let success = false;
        try { success = document.execCommand('copy'); } catch (e) { success = false; }
        document.body.removeChild(ta);
        return success;
    }

    // ==================== حافظة النصوص المتعددة الداخلية (Smart Clipboard Ring) ====================
    // بيسمع لأي عملية Copy حصلت جوه الصفحة (تحديد ونسخ عادي، أو نسخ عن طريق أزرار الأداة نفسها -
    // كلاهما بيمرّ من حدث 'copy' الطبيعي) ويخزن آخر 10 نصوص مختلفة. Ctrl+Shift+V وأنت جوه أي
    // مربع كتابة بيفتح منيو صغير تحت الماوس تختار منه بالسهم + Enter فيتلزق النص فوراً في مكان الكتابة.
    const CLIPBOARD_RING_MAX = 10;
    let clipboardRing = [];
    let lastMouseX = 0, lastMouseY = 0;

    document.addEventListener('mousemove', (e) => { lastMouseX = e.clientX; lastMouseY = e.clientY; });

    function pushClipboardRing(text) {
        text = (text || '').trim();
        if (!text) return;
        clipboardRing = clipboardRing.filter(t => t !== text);
        clipboardRing.unshift(text);
        if (clipboardRing.length > CLIPBOARD_RING_MAX) clipboardRing.length = CLIPBOARD_RING_MAX;
    }

    document.addEventListener('copy', () => {
        // بنقرأ النص من مكان التحديد الفعلي وقت النسخة - مربوط بالـ activeElement عشان مربوطات
        // الكتابة (textarea/input) مش بتستخدم Selection API العادية للنص الداخلي بتاعها.
        let text = '';
        const active = document.activeElement;
        if (active && (active.tagName === 'TEXTAREA' || active.tagName === 'INPUT')) {
            const s = active.selectionStart, en = active.selectionEnd;
            if (typeof s === 'number' && typeof en === 'number' && en > s) {
                text = active.value.slice(s, en);
            } else {
                text = active.value || '';
            }
        } else {
            try { text = (document.getSelection() || '').toString(); } catch (e) { /* تجاهل */ }
        }
        pushClipboardRing(text);
    }, true);

    function setNativeFieldValue(el, value) {
        const proto = el.tagName === 'TEXTAREA' ? window.HTMLTextAreaElement.prototype : window.HTMLInputElement.prototype;
        const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
        setter.call(el, value);
        el.dispatchEvent(new Event('input', { bubbles: true }));
        el.dispatchEvent(new Event('change', { bubbles: true }));
    }

    function insertTextAtCursor(el, text) {
        if (!el || (el.tagName !== 'TEXTAREA' && el.tagName !== 'INPUT')) return;
        const start = typeof el.selectionStart === 'number' ? el.selectionStart : el.value.length;
        const end = typeof el.selectionEnd === 'number' ? el.selectionEnd : el.value.length;
        const newVal = el.value.slice(0, start) + text + el.value.slice(end);
        setNativeFieldValue(el, newVal);
        const pos = start + text.length;
        try { el.selectionStart = el.selectionEnd = pos; } catch (e) { /* تجاهل */ }
    }

    function ensureClipboardRingStyles() {
        if (document.getElementById('tx-clip-ring-style')) return;
        const style = document.createElement('style');
        style.id = 'tx-clip-ring-style';
        style.textContent = `
            .tx-clip-menu {
                position: fixed; z-index: 200010; width: 250px; max-height: 260px; overflow-y: auto;
                background: linear-gradient(165deg, rgba(32,32,42,0.92), rgba(14,14,19,0.96));
                backdrop-filter: blur(20px) saturate(180%);
                -webkit-backdrop-filter: blur(20px) saturate(180%);
                border: 1px solid rgba(167,139,250,0.3); border-radius: 14px;
                padding: 6px; box-shadow: 0 16px 40px rgba(0,0,0,0.55), 0 0 24px rgba(124,58,237,0.25);
                font-family: 'Cairo', 'Segoe UI', Tahoma, sans-serif; direction: rtl;
                animation: tx-pop-in 0.15s ease;
            }
            .tx-clip-menu.tx-clip-closing { animation: tx-clip-fade-out 0.14s ease forwards; }
            @keyframes tx-clip-fade-out { to { opacity: 0; transform: scale(0.96); } }
            .tx-clip-item {
                padding: 7px 10px; border-radius: 9px; color: #e2e8f0; font-size: 12px;
                white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
                cursor: pointer; transition: background 0.12s ease; margin-bottom: 2px;
            }
            .tx-clip-item:hover { background: rgba(255,255,255,0.08); }
            .tx-clip-item.tx-clip-selected { background: rgba(124,58,237,0.4); color: #fff; }
        `;
        document.head.appendChild(style);
    }

    function showClipboardRingMenu(targetEl) {
        if (!clipboardRing.length) {
            showToast('لسه مفيش حاجة اتنسخت في الصفحة دي عشان تختار منها', true);
            return;
        }
        ensureClipboardRingStyles();
        document.querySelectorAll('.tx-clip-menu').forEach(m => m.remove());

        const menu = document.createElement('div');
        menu.className = 'tx-clip-menu';
        const left = Math.min(lastMouseX, window.innerWidth - 262);
        const top = Math.min(lastMouseY, window.innerHeight - 270);
        menu.style.left = Math.max(4, left) + 'px';
        menu.style.top = Math.max(4, top) + 'px';

        let selectedIndex = 0;
        const items = clipboardRing.map((text, i) => {
            const item = document.createElement('div');
            item.className = 'tx-clip-item' + (i === 0 ? ' tx-clip-selected' : '');
            item.textContent = text.length > 55 ? text.slice(0, 55) + '…' : text;
            item.title = text;
            item.onclick = () => choose(i);
            menu.appendChild(item);
            return item;
        });

        function highlight() {
            items.forEach((it, i) => it.classList.toggle('tx-clip-selected', i === selectedIndex));
            items[selectedIndex].scrollIntoView({ block: 'nearest' });
        }

        function closeMenu() {
            menu.classList.add('tx-clip-closing');
            setTimeout(() => menu.remove(), 150);
            document.removeEventListener('keydown', keyHandler, true);
            document.removeEventListener('mousedown', outsideHandler, true);
        }

        function choose(i) {
            insertTextAtCursor(targetEl, clipboardRing[i]);
            closeMenu();
        }

        function keyHandler(e) {
            if (e.key === 'ArrowDown') { e.preventDefault(); selectedIndex = Math.min(items.length - 1, selectedIndex + 1); highlight(); }
            else if (e.key === 'ArrowUp') { e.preventDefault(); selectedIndex = Math.max(0, selectedIndex - 1); highlight(); }
            else if (e.key === 'Enter') { e.preventDefault(); choose(selectedIndex); }
            else if (e.key === 'Escape') { e.preventDefault(); closeMenu(); }
        }

        function outsideHandler(e) {
            if (!menu.contains(e.target)) closeMenu();
        }

        document.addEventListener('keydown', keyHandler, true);
        setTimeout(() => document.addEventListener('mousedown', outsideHandler, true), 0);
        document.body.appendChild(menu);
    }

    let lastCollectedText = '';
    let lastCollectedCount = 0;

    async function copySegments(btn) {
        txBtnBusy(btn, 'جاري السحب...');
        btn.disabled = true;

        const result = await collectAllSegments();

        txBtnReset(btn);
        btn.disabled = false;

        if (!result || !result.text) {
            showToast('مفيش سيجمنتات اتلقطت (بعد استبعاد التاجز)', true);
            return;
        }

        lastCollectedText = result.text;
        lastCollectedCount = result.count;
        const method = result.usedFast ? 'لحظي من بيانات الموقع' : (result.usedNav ? 'عبر Navigation' : 'عبر سكرول');

        let ok = fallbackCopy(lastCollectedText);
        if (!ok) {
            await sleep(120);
            ok = fallbackCopy(lastCollectedText);
        }

        if (ok) {
            txToolFeedback(btn, 'اتنسخ ' + result.count + ' سيجمنت', 'تم نسخ ' + result.count + ' سيجمنت (بدون تاجز) - ' + method);
        } else {
            showToast('اتجمعت البيانات بس النسخ التلقائي فشل - دوس "📎 نسخ الأخير"', true);
        }
    }

    let copyAllBtnRef = null;
    function addCopyButton() {
        const btn = document.createElement('button');
        txInitToolBtn(btn, 'copyAll', 'copy', 'نسخ كل السيجمنتات', 'primary');

        btn.onclick = () => copySegments(btn);
        document.body.appendChild(btn);
        copyAllBtnRef = btn;
    }

    function copyLastCollected(btn) {
        if (!lastCollectedText) {
            showToast('مفيش بيانات مجمّعة بعد — دوس "نسخ كل السيجمنتات" الأول', true);
            return;
        }
        const ok = fallbackCopy(lastCollectedText);
        if (ok) txToolFeedback(btn, 'اتنسخ ' + lastCollectedCount + ' سيجمنت', 'تم نسخ ' + lastCollectedCount + ' سيجمنت ✅');
        else showToast('فشل النسخ برضه — جرب تاني بسرعة', true);
    }

    function addCopyLastButton() {
        const btn = document.createElement('button');
        txInitToolBtn(btn, 'copyLast', 'clipboard', 'نسخ الأخير', 'primary');

        btn.onclick = () => copyLastCollected(btn);
        document.body.appendChild(btn);
    }

    // ==================== الجزء 2: سكرول أفقي ذكي ====================
    function findScrollableTarget(waveformContainer) {
        const candidates = waveformContainer.querySelectorAll('*');
        for (const el of candidates) {
            if (el.scrollWidth > el.clientWidth + 5) {
                return el;
            }
        }
        return waveformContainer.querySelector('wave') || waveformContainer;
    }

    // (v28.11.3) نفس فكرة تحسين عيون الماسكوت (v28.11.2) اتطبّقت هنا: قبل كده findScrollableTarget
    // كانت بتتنادى من الصفر (querySelectorAll('*') على كل عناصر الموجة) مع *كل* نبضة عجلة ماوس -
    // يعني ممكن تتكرر عشرات المرات في الثانية لو المستخدم بيسكرول بسرعة. الحل: نكاش (cache) العنصر
    // القابل للسكرول أول مرة نلاقيه لكل waveformContainer، ونعيد استخدام نفس النسخة تاني وتالت من
    // غير إعادة بحث. مانلغيش الكاش إلا لو فعلاً حصل تغيير جوه بنية الموجة (MutationObserver خفيف على
    // childList/subtree بس - بيتنادى لما الـDOM يتغيّر فعلاً زي تحميل صوت جديد أو زوم، مش مع كل حركة)
    // أو لو العنصر المكاش بقى مقطوع عن الصفحة (isConnected false). كمان جمّعنا كل الـdeltaY اللي بييجي
    // من نبضات wheel متلاحقة في متغيّر واحد وبنطبّقهم دفعة واحدة جوه requestAnimationFrame - أقصى
    // تحديث فعلي للسكرول بقى مرة كل فريم (~60 مرة/ثانية) بدل ما يتطبّق فوراً ومنفصل مع كل نبضة لوحدها.
    function setupWaveformScroll() {
        const waveformContainer = document.querySelector('#waveform');
        if (!waveformContainer) return false;
        if (waveformContainer.dataset.scrollBound) return true;

        let cachedScrollTarget = null;
        const getScrollTarget = () => {
            if (!cachedScrollTarget || !cachedScrollTarget.isConnected) {
                cachedScrollTarget = findScrollableTarget(waveformContainer);
            }
            return cachedScrollTarget;
        };

        const invalidateScrollTargetCache = new MutationObserver(() => { cachedScrollTarget = null; });
        invalidateScrollTargetCache.observe(waveformContainer, { childList: true, subtree: true });

        let pendingWheelDeltaY = 0;
        let wheelFrameScheduled = false;
        const flushWheelDelta = () => {
            wheelFrameScheduled = false;
            const target = getScrollTarget();
            if (!target) { pendingWheelDeltaY = 0; return; }
            target.scrollLeft += pendingWheelDeltaY;
            pendingWheelDeltaY = 0;
        };

        waveformContainer.addEventListener('wheel', (e) => {
            // لازم نمنع السكرول الطبيعي فورًا مع كل نبضة (زي الأول بالظبط) عشان الصفحة متسكرلش
            // عمودي بدل الأفقي المقصود - التأجيل بيحصل بس في التطبيق الفعلي على scrollLeft.
            e.preventDefault();
            e.stopPropagation();
            pendingWheelDeltaY += e.deltaY;
            if (!wheelFrameScheduled) {
                wheelFrameScheduled = true;
                requestAnimationFrame(flushWheelDelta);
            }
        }, { passive: false });

        let touchStartX = 0, touchStartScroll = 0, touchTarget = null;
        waveformContainer.addEventListener('touchstart', (e) => {
            touchTarget = getScrollTarget();
            touchStartX = e.touches[0].pageX;
            touchStartScroll = touchTarget ? touchTarget.scrollLeft : 0;
        }, { passive: true });

        waveformContainer.addEventListener('touchmove', (e) => {
            if (!touchTarget) return;
            e.preventDefault();
            const delta = (touchStartX - e.touches[0].pageX) * 1.5;
            touchTarget.scrollLeft = touchStartScroll + delta;
        }, { passive: false });

        waveformContainer.dataset.scrollBound = 'true';
        console.log('[Scroll] تم تفعيل السكرول الأفقي على #waveform ✅');
        return true;
    }

    // ملحوظة: الموقع SPA (Vue) - لما تتنقل من تاسك لتاسك من غير Refresh كامل للصفحة، بيستبدل عناصر
    // زي #waveform / #changyuliu_table بعناصر DOM جديدة. لو وقفنا الفحص الدوري بعد أول مرة ينجح،
    // مش هنعرف نربط تاني على العنصر الجديد. فبنسيبه شغال طول الوقت (تكلفته بسيطة جداً لما مفيش تغيير).
    runVisibleInterval(() => { setupWaveformScroll(); }, 800);

    // ==================== الجزء 4: فحص المسافات الزائدة + المسافة المزدوجة ====================
    // ==================== (v29.1) تحديد مكان مشاكل المسافات بالظبط ====================
    // بدل "فيه مسافة زايدة في أول أو آخر" بس، بنرجّع لكل مشكلة: مكانها (أول/آخر/بين كلمتين)، وعدد المسافات،
    // وأقرب كلمة قبلها/بعدها. الشرط هنا نفس شروط الفحص القديم بالظبط (نفس الـregex) فمفيش نتيجة بتتغيّر - بس بقت مفصّلة.
    const WS_PUNCT_CHARS = '،؛:؟!.';
    const wsDetailMap = { lead: new Map(), dbl: new Map() }; // serial -> [نصوص تفصيلية]
    function wsDescribeChars(ws) {
        const n = ws.length;
        const odd = /[^ ]/.test(ws);
        const what = !odd ? null : (/\t/.test(ws) ? 'Tab' : (/\u00A0/.test(ws) ? 'مسافة غير قابلة للكسر (NBSP)' : (/[\r\n]/.test(ws) ? 'سطر جديد' : 'فراغ غريب')));
        const base = n === 1 ? 'مسافة واحدة' : (n === 2 ? 'مسافتين' : n + ' مسافات');
        return what ? base + ' (فيها ' + what + ')' : base;
    }
    function wsWordBefore(text, idx) {
        const m = text.slice(0, idx).match(/(\S+)$/);
        return m ? (m[1].length > 16 ? '…' + m[1].slice(-16) : m[1]) : null;
    }
    function wsWordAfter(text, idx) {
        const m = text.slice(idx).match(/^(\S+)/);
        return m ? (m[1].length > 16 ? m[1].slice(0, 16) + '…' : m[1]) : null;
    }
    // بترجّع { lead: [..], dbl: [..] } - مصفوفات رسايل (فاضية لو مفيش مشكلة)
    function describeWhitespaceIssues(text) {
        const out = { lead: [], dbl: [] };
        if (!text) return out;
        const lead = text.match(/^\s+/);
        const trail = text.match(/\s+$/);
        const onlyWs = !text.trim();
        if (onlyWs) {
            out.lead.push('السيجمنت كله مسافات فاضية (' + wsDescribeChars(text) + ') من غير أي كلام');
            return out;
        }
        if (lead) {
            const nxt = wsWordAfter(text, lead[0].length);
            out.lead.push('' + wsDescribeChars(lead[0]) + ' زيادة في أول السيجمنت، قبل كلمة «' + nxt + '»');
        }
        if (trail) {
            const prv = wsWordBefore(text, text.length - trail[0].length);
            out.lead.push('' + wsDescribeChars(trail[0]) + ' زيادة في آخر السيجمنت، بعد كلمة «' + prv + '»');
        }
        const re = /\s{2,}/g;
        let m;
        while ((m = re.exec(text)) !== null) {
            const start = m.index, end = start + m[0].length;
            if (start === 0 || end === text.length) continue; // دي مسافات أول/آخر، اتغطّت فوق
            const pc = text[start - 1], nc = text[end];
            if (WS_PUNCT_CHARS.includes(pc) || WS_PUNCT_CHARS.includes(nc)) continue; // نفس استثناء الفحص القديم
            out.dbl.push(wsDescribeChars(m[0]) + ' ورا بعض بين «' + wsWordBefore(text, start) + '» و«' + wsWordAfter(text, end) + '»');
        }
        return out;
    }
    function wsSerialItemText(serial, kind) {
        const d = wsDetailMap[kind].get(serial);
        return 'سيجمنت ' + serial + (d && d.length ? ' — 📏 ' + d.join(' | 📏 ') : '');
    }

    function checkWhitespaceIssues() {
        const rows = document.querySelectorAll('#changyuliu_table > tr');
        const leadTrailIssues = [];
        const doubleSpaceIssues = [];
        const doubleSpaceRegex = /[^\s،؛:؟!.]\s{2,}[^\s،؛:؟!.]/;

        rows.forEach(row => {
            const snap = collectRowSnapshot(row);
            if (!snap) return;
            const raw = snap.raw;

            let hasIssue = false;

            if (raw && /^\s|\s$/.test(raw)) {
                leadTrailIssues.push(snap.serial);
                wsDetailMap.lead.set(snap.serial, describeWhitespaceIssues(raw).lead);
                hasIssue = true;
            }

            if (raw && doubleSpaceRegex.test(raw)) {
                doubleSpaceIssues.push(snap.serial);
                wsDetailMap.dbl.set(snap.serial, describeWhitespaceIssues(raw).dbl);
                hasIssue = true;
            }

            setRowStatus(row, hasIssue ? 'error' : null);
        });

        return { leadTrailIssues, doubleSpaceIssues };
    }

    async function auditWhitespace(btn) {
        txBtnBusy(btn, 'جاري الفحص...');
        btn.disabled = true;

        const navButtons = findNavButtons();
        const allLeadTrail = new Set();
        const allDoubleSpace = new Set();

        const r0 = checkWhitespaceIssues();
        r0.leadTrailIssues.forEach(s => allLeadTrail.add(s));
        r0.doubleSpaceIssues.forEach(s => allDoubleSpace.add(s));

        if (navButtons.length > 0) {
            for (const navBtn of navButtons) {
                navBtn.click();
                await sleep(500);
                const result = checkWhitespaceIssues();
                result.leadTrailIssues.forEach(s => allLeadTrail.add(s));
                result.doubleSpaceIssues.forEach(s => allDoubleSpace.add(s));
            }
        }

        txBtnReset(btn);
        btn.disabled = false;

        const sections = [];
        if (allLeadTrail.size > 0) {
            sections.push({
                heading: '📏 مسافة زيادة في أول/آخر السيجمنت',
                items: Array.from(allLeadTrail).sort((a, b) => a - b).map(s => ({ text: wsSerialItemText(s, 'lead'), type: 'warn' }))
            });
        }
        if (allDoubleSpace.size > 0) {
            sections.push({
                heading: '📏 مسافة مزدوجة بين كلمتين جوه السيجمنت',
                items: Array.from(allDoubleSpace).sort((a, b) => a - b).map(s => ({ text: wsSerialItemText(s, 'dbl'), type: 'warn' }))
            });
        }

        showResultsPanel('🔍 فحص المسافات', sections, 'مفيش أي مشاكل مسافات', {
            label: '🔧 تصليح المسافات',
            onClick: async () => {
                const serialsToFix = new Set([...allLeadTrail, ...allDoubleSpace]);
                return await fixSegmentsBySerial(serialsToFix, (raw) => raw.trim().replace(/\s{2,}/g, ' '));
            }
        });
    }

    function addWhitespaceButton() {
        const btn = document.createElement('button');
        txInitToolBtn(btn, 'whitespace', 'search', 'فحص المسافات', 'review');

        btn.onclick = () => auditWhitespace(btn);
        document.body.appendChild(btn);
    }

    // ==================== الجزء 4.5: فحص الإنجليزي الزايد + التشكيل العربي ====================
    function checkEnglishAndTashkeel() {
        const rows = document.querySelectorAll('#changyuliu_table > tr');
        const englishIssues = [];
        const tashkeelIssues = [];
        const tashkeelRegex = TASHKEEL_TEST_RE;

        rows.forEach(row => {
            const snap = collectRowSnapshot(row);
            if (!snap || !snap.trimmed) return;
            const raw = snap.trimmed;

            const englishWords = countPureEnglishWords(raw);
            const hasTashkeel = tashkeelRegex.test(raw);
            const hasThreeEnglishWords = englishWords.length >= 3;

            if (hasThreeEnglishWords || hasTashkeel) {
                if (hasThreeEnglishWords) englishIssues.push({ serial: snap.serial, count: englishWords.length, words: englishWords.join(', ') });
                if (hasTashkeel) tashkeelIssues.push(snap.serial);
                setRowStatus(row, 'warn');
            } else {
                setRowStatus(row, null);
            }
        });

        return { englishIssues, tashkeelIssues };
    }

    async function auditEnglishAndTashkeel(btn) {
        txBtnBusy(btn, 'جاري الفحص...');
        btn.disabled = true;

        const navButtons = findNavButtons();
        let allEnglishIssues = [];
        const allTashkeelIssues = new Set();

        const r0 = checkEnglishAndTashkeel();
        allEnglishIssues.push(...r0.englishIssues);
        r0.tashkeelIssues.forEach(s => allTashkeelIssues.add(s));

        if (navButtons.length > 0) {
            for (const navBtn of navButtons) {
                navBtn.click();
                await sleep(500);
                const result = checkEnglishAndTashkeel();
                allEnglishIssues.push(...result.englishIssues);
                result.tashkeelIssues.forEach(s => allTashkeelIssues.add(s));
            }
        }
        allEnglishIssues = dedupeBySerial(allEnglishIssues);

        txBtnReset(btn);
        btn.disabled = false;

        const sections = [];
        if (allEnglishIssues.length > 0) {
            sections.push({
                heading: '🔤 سيجمنتات فيها 3 كلمات إنجليزي أو أكتر',
                items: allEnglishIssues.map(item => ({
                    text: 'سيجمنت ' + item.serial + ' — ' + item.count + ' كلمة: ' + item.words,
                    type: 'warn'
                }))
            });
        }
        if (allTashkeelIssues.size > 0) {
            sections.push({
                heading: '🚫 سيجمنتات فيها تشكيل عربي',
                items: Array.from(allTashkeelIssues).sort((a, b) => a - b).map(s => ({ text: 'سيجمنت ' + s, type: 'warn' }))
            });
        }

        showResultsPanel('🈯 فحص إنجليزي/تشكيل', sections, 'مفيش سيجمنتات فيها 3 كلمات إنجليزي أو أي تشكيل عربي',
            allTashkeelIssues.size > 0 ? {
                label: '🔧 صلح التشكيل بس',
                onClick: async () => {
                    return await fixSegmentsBySerial(allTashkeelIssues, (raw) => stripTashkeel(raw));
                }
            } : null
        );
    }

    function addEnglishTashkeelButton() {
        const btn = document.createElement('button');
        txInitToolBtn(btn, 'englishTashkeel', 'type', 'فحص إنجليزي/تشكيل', 'review');

        btn.onclick = () => auditEnglishAndTashkeel(btn);
        document.body.appendChild(btn);
    }

