        'ثانيه': 'ثانية', 'سنه': 'سنة', 'فتره': 'فترة', 'مده': 'مدة', 'لحظه': 'لحظة', 'لعبه': 'لعبة',
        'مباراه': 'مباراة', 'بطوله': 'بطولة', 'كوره': 'كورة', 'زياده': 'زيادة', 'نهايه': 'نهاية',
        'بدايه': 'بداية', 'اجازة': 'إجازة', 'عطله': 'عطلة', 'اللة': 'الله', 'واللة': 'والله', 'باللة': 'بالله',
