    // ونشيل أي هاشتاج غلط اتحط حواليها قبل كده (#أه#) في autoFixWritingIssues تحت.
    const HAMZA_AH_WORD_REGEX = /^أه$/;
    function isAllHamzaAhContent(content) {
        const trimmed = normalizeSpaces(content);
        if (!trimmed) return false;
        const tokens = trimmed.split(' ').filter(Boolean);
        return tokens.length > 0 && tokens.every(t => HAMZA_AH_WORD_REGEX.test(t));
    }

