                let vis = 0; all.forEach(c => { if (c.style.display !== 'none') vis++; });
                const hideList = !vis || (sec.classList.contains('collapsed') && !active); // (v29.20.0) القسم المقفول بيتفتح مؤقتاً لو فيه فلتر شغال
